    const newItem = {
      ...item,
      id: item.id || `v_custom_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
      wrongCount: item.wrongCount || 0,
      srsLevel: item.srsLevel || 0,
      isMastered: false,
      createdAt: new Date().toISOString()
    };
    list.unshift(newItem);
