class GenreWordMasterComponent {
  static container = null;
  static onNavigate = null;

  static state = {
    view: 'genre_select', // 'genre_select' | 'word_list' | 'game' | 'game_result'
    activeGenreId: 'body',
    searchQuery: '',
    
    // ゲーム状態
    gameQuestions: [],
    gameCurrentIndex: 0,
    currentQuestion: null,
    gameChoices: [],
    gameScore: 0,
    gameCombo: 0,
    gameMaxCombo: 0,
    gameCorrectCount: 0,
    hasAnswered: false,
    selectedChoice: null,
    isCorrect: false,
    mistakes: [],
    mascotMood: 'idle',
    mascotMessage: '準備はいいかい？全問正解を目指そう！🐧'
  };

  static render(container, onNavigate) {
    this.container = container;
    this.onNavigate = onNavigate;
    this.renderUI();
  }

  static getGenreWords(genreId) {
    const rawVocab = StorageService.getVocabulary();
    return rawVocab.filter(w => w.genreId === genreId);
  }

  static renderUI() {
    if (!this.container) return;

    if (this.state.view === 'genre_select') {
      this.renderGenreSelectUI();
    } else if (this.state.view === 'word_list') {
      this.renderWordListUI();
    } else if (this.state.view === 'game') {
      this.renderGameUI();
    } else if (this.state.view === 'game_result') {
      this.renderGameResultUI();
    }
  }

  // ==========================================
  // 1. ジャンル選択画面
  // ==========================================
  static renderGenreSelectUI() {
    const allVocab = StorageService.getVocabulary();

    const genreStats = GENRE_CONFIG.map(g => {
      const words = allVocab.filter(w => w.genreId === g.id);
      return {
        ...g,
        count: words.length,
        samples: words.slice(0, 4).map(w => w.mongolian).join('・')
      };
    });

    const totalGenreWords = genreStats.reduce((sum, g) => sum + g.count, 0);

    this.container.innerHTML = `
      <div class="animate-fade-in max-w-5xl mx-auto px-4 py-6 space-y-6">
        
        <!-- ヘッダーバナー -->
        <div class="bg-gradient-to-r from-emerald-600 via-teal-600 to-cyan-600 rounded-3xl p-6 sm:p-8 text-white shadow-xl relative overflow-hidden">
          <div class="absolute -right-6 -bottom-6 text-8xl opacity-15 pointer-events-none">🏷️</div>
          <div class="relative z-10 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
              <div class="inline-flex items-center gap-2 bg-white/20 backdrop-blur-md px-3.5 py-1 rounded-full text-xs font-bold mb-2">
                <span>⚡ テーマ別単語特訓</span>
                <span>•</span>
                <span>全7ジャンル (${totalGenreWords}語)</span>
              </div>
              <h2 class="text-2xl sm:text-3xl font-black tracking-tight">
                ジャンル別単語マスター ＆ クイズ
              </h2>
              <p class="text-emerald-100 text-sm mt-1 max-w-xl">
                身体の部位、学校、衣類、料理、日用品、野菜・果物、方位をジャンルごとに整理して学習。単語帳で音声を確認し、ジャンル別単語ゲームで即座に記憶に定着させましょう！
              </p>
            </div>
            <div class="flex items-center gap-2">
              <button type="button" id="btn-genre-home-back" class="bg-white/20 hover:bg-white/30 text-white px-4 py-2 rounded-xl text-sm font-bold transition-all flex items-center gap-1.5 shadow-sm">
                <span>← ホームへ</span>
              </button>
            </div>
          </div>
        </div>

        <!-- ジャンルカード一覧 (7分野) -->
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          ${genreStats.map(g => `
            <div class="bg-white rounded-3xl border border-slate-200/90 shadow-sm hover:shadow-md transition-all p-5 flex flex-col justify-between space-y-4 group">
              <div>
                <div class="flex items-center justify-between mb-3">
                  <span class="text-3xl p-2.5 bg-slate-50 rounded-2xl border border-slate-100 group-hover:scale-110 transition-transform">
                    ${g.icon}
                  </span>
                  <span class="text-xs font-black px-3 py-1 rounded-full ${g.badgeClass}">
                    ${g.count} 語収録
                  </span>
                </div>
                <h3 class="text-lg font-black text-slate-800 flex items-center gap-1.5">
                  ${g.titleJa}
                </h3>
                <div class="text-xs font-bold text-slate-500 mb-2">
                  ${g.titleMn}
                </div>
                <p class="text-xs text-slate-600 leading-relaxed mb-3">
                  ${g.description}
                </p>
                <div class="text-[11px] text-slate-400 bg-slate-50 p-2 rounded-xl border border-slate-100 font-mono">
                  💡 例: ${g.samples || '単語収集中'}
                </div>
              </div>

              <!-- アクションボタン -->
              <div class="grid grid-cols-2 gap-2 pt-2 border-t border-slate-100">
                <button type="button" class="btn-open-wordlist w-full py-2 px-3 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold transition-all flex items-center justify-center gap-1" data-genre-id="${g.id}">
                  <span>📖 単語帳</span>
                </button>
                <button type="button" class="btn-start-genre-game w-full py-2 px-3 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 hover:to-teal-600 text-white text-xs font-black shadow-xs active:scale-95 transition-all flex items-center justify-center gap-1" data-genre-id="${g.id}">
                  <span>🎮 ゲーム</span>
                </button>
              </div>
            </div>
          `).join('')}
        </div>

      </div>
    `;

    this.bindGenreSelectEvents();
  }

  static bindGenreSelectEvents() {
    const homeBtn = this.container.querySelector('#btn-genre-home-back');
    if (homeBtn && this.onNavigate) {
      homeBtn.addEventListener('click', () => this.onNavigate('home'));
    }

    this.container.querySelectorAll('.btn-open-wordlist').forEach(btn => {
      btn.addEventListener('click', () => {
        const gid = btn.dataset.genreId;
        this.state.activeGenreId = gid;
        this.state.searchQuery = '';
        this.state.view = 'word_list';
        this.renderUI();
      });
    });

    this.container.querySelectorAll('.btn-start-genre-game').forEach(btn => {
      btn.addEventListener('click', () => {
        const gid = btn.dataset.genreId;
        this.startGenreGame(gid);
      });
    });
  }

  // ==========================================
  // 2. 単語帳一覧画面（音声再生・検索対応）
  // ==========================================
  static renderWordListUI() {
    const genre = GENRE_CONFIG.find(g => g.id === this.state.activeGenreId) || GENRE_CONFIG[0];
    let words = this.getGenreWords(genre.id);

    // 検索フィルタ
    if (this.state.searchQuery.trim()) {
      const q = this.state.searchQuery.trim().toLowerCase();
      words = words.filter(w => 
        (w.mongolian && w.mongolian.toLowerCase().includes(q)) ||
        (w.japanese && w.japanese.toLowerCase().includes(q)) ||
        (w.pronunciation && w.pronunciation.includes(q))
      );
    }

    this.container.innerHTML = `
      <div class="animate-fade-in max-w-5xl mx-auto px-4 py-6 space-y-6">
        
        <!-- ナビバー -->
        <div class="flex flex-wrap items-center justify-between gap-3 bg-white p-4 rounded-2xl border border-slate-200 shadow-xs">
          <div class="flex items-center gap-2">
            <button type="button" id="btn-back-to-genres" class="p-2 rounded-xl text-slate-500 hover:text-slate-800 hover:bg-slate-100 transition-colors">
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path>
              </svg>
            </button>
            <div class="flex items-center gap-2">
              <span class="text-2xl">${genre.icon}</span>
              <div>
                <h2 class="text-base sm:text-lg font-black text-slate-800">
                  ${genre.titleJa} 単語帳
                </h2>
                <div class="text-[11px] font-bold text-slate-400">
                  ${genre.titleMn} • ${words.length} 語表示
                </div>
              </div>
            </div>
          </div>

          <div class="flex items-center gap-2">
            <button type="button" id="btn-launch-game-from-list" class="bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 hover:to-teal-600 text-white text-xs font-black px-4 py-2 rounded-xl shadow-xs active:scale-95 transition-all flex items-center gap-1.5">
              <span>🎮 このジャンルでゲーム開始</span>
            </button>
          </div>
        </div>

        <!-- 検索バー ＆ ジャンル切替タブ -->
        <div class="flex flex-col sm:flex-row items-center gap-3">
          <div class="relative flex-1 w-full">
            <span class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">🔍</span>
            <input 
              type="text" 
              id="genre-word-search" 
              value="${this.state.searchQuery}" 
              placeholder="モンゴル語・日本語・カタカナで検索..." 
              class="w-full pl-9 pr-4 py-2.5 rounded-xl border border-slate-200 bg-white text-sm text-slate-800 focus:outline-hidden focus:ring-2 focus:ring-emerald-500 shadow-2xs"
            />
          </div>

          <!-- 他ジャンルへのクイック切り替え -->
          <div class="flex items-center gap-1 overflow-x-auto w-full sm:w-auto pb-1 sm:pb-0">
            ${GENRE_CONFIG.map(g => `
              <button type="button" class="btn-switch-genre px-2.5 py-1.5 rounded-xl text-xs font-bold shrink-0 transition-all ${
                g.id === genre.id ? 'bg-slate-900 text-white shadow-xs' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-100'
              }" data-genre-id="${g.id}">
                <span>${g.icon}</span>
                <span class="hidden md:inline">${g.titleJa}</span>
              </button>
            `).join('')}
          </div>
        </div>

        <!-- 単語一覧グリッド（ビジュアルイラスト付き・要件10準拠） -->
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          ${words.map(w => `
            <div class="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 p-4 shadow-2xs hover:shadow-md transition-all flex flex-col justify-between space-y-3">
              <div>
                <div class="flex items-start justify-between gap-2.5">
                  <div class="flex items-center gap-3">
                    ${(typeof getWordIllustrationHTML === 'function') ? getWordIllustrationHTML(w, { size: 'lg' }) : ''}
                    <div>
                      <div class="text-xl font-black text-slate-900 dark:text-white tracking-wide font-sans">
                        ${w.mongolian}
                      </div>
                      ${(typeof isPronunciationCautionWord === 'function' && isPronunciationCautionWord(w) && w.pronunciation) ? `
                        <div class="text-xs font-bold text-amber-600 dark:text-amber-400">
                          ⚠️ [ ${w.pronunciation} ]
                        </div>
                      ` : ''}
                    </div>
                  </div>
                  <button type="button" class="btn-play-word-audio p-2 rounded-xl bg-emerald-50 dark:bg-slate-700 hover:bg-emerald-100 dark:hover:bg-slate-600 text-emerald-700 dark:text-emerald-400 transition-colors cursor-pointer shrink-0" data-word="${w.mongolian}" title="音声を聴く">
                    <span class="text-base">🔊</span>
                  </button>
                </div>

                <div class="mt-2.5 pt-2.5 border-t border-slate-100 dark:border-slate-700">
                  <div class="text-sm font-black text-slate-800 dark:text-slate-100">
                    ${w.japanese}${w.altMongolian ? ` <span class="text-xs font-normal text-slate-500 dark:text-slate-400">(${w.altMongolian})</span>` : ''}
                  </div>
                  <div class="text-[11px] text-slate-400 dark:text-slate-400 font-medium flex items-center justify-between">
                    <span>品詞: ${w.pos || '名詞'}</span>
                    ${w.caseGovernment ? `<span class="px-2 py-0.5 rounded-full bg-purple-100 dark:bg-purple-950 text-purple-900 dark:text-purple-200 font-black text-[10px] border border-purple-200 dark:border-purple-800">⚡ ${w.caseGovernment}</span>` : ''}
                  </div>
                </div>

                ${w.caseGovernment ? `
                  <div class="mt-2 p-2.5 bg-gradient-to-br from-purple-50 to-indigo-50/50 dark:from-purple-950/40 dark:to-indigo-950/40 rounded-xl border border-purple-200 dark:border-purple-800 text-xs space-y-1">
                    <div class="font-black text-purple-950 dark:text-purple-200 flex items-center gap-1.5">
                      <span>⚡ 格支配:</span>
                      <span class="text-purple-800 dark:text-purple-300 font-bold">${w.caseGovernment}</span>
                    </div>
                    ${w.caseNote ? `<div class="text-[11px] text-purple-900 dark:text-purple-300 leading-relaxed">${w.caseNote}</div>` : ''}
                  </div>
                ` : ''}

                ${w.note ? `
                  <div class="mt-2 text-[11px] text-slate-500 dark:text-slate-400 bg-slate-50 dark:bg-slate-700/50 p-2 rounded-xl border border-slate-100 dark:border-slate-700 leading-relaxed">
                    💡 ${w.note}
                  </div>
                ` : ''}

                ${w.exampleMn ? `
                  <div class="mt-2 p-2 bg-slate-50 dark:bg-slate-900/60 rounded-xl border border-slate-100 dark:border-slate-700/60 text-xs space-y-0.5">
                    <div class="font-bold text-slate-700 dark:text-slate-200 font-sans">${w.exampleMn}</div>
                    <div class="text-[11px] text-slate-500 dark:text-slate-400">${w.exampleJa || ''}</div>
                  </div>
                ` : ''}

                ${(typeof getWordEtymologyHTML === 'function') ? getWordEtymologyHTML(w, w.mongolian) : ''}
                ${(typeof getWordMnemonicHTML === 'function') ? getWordMnemonicHTML(w, w.mongolian) : ''}
                ${(typeof getSimilarWordDistinctionHTML === 'function') ? getSimilarWordDistinctionHTML(w, w.mongolian) : ''}
              </div>
            </div>
          `).join('')}
        </div>

        ${words.length === 0 ? `
          <div class="text-center py-12 bg-white rounded-3xl border border-slate-200 p-8 space-y-2">
            <div class="text-4xl">🔍</div>
            <div class="text-base font-bold text-slate-700">該当する単語が見つかりませんでした</div>
            <div class="text-xs text-slate-400">検索キーワードを変更するかクリアしてください</div>
          </div>
        ` : ''}

      </div>
    `;

    this.bindWordListEvents();
  }

  static bindWordListEvents() {
    const backBtn = this.container.querySelector('#btn-back-to-genres');
    if (backBtn) {
      backBtn.addEventListener('click', () => {
        this.state.view = 'genre_select';
        this.renderUI();
      });
    }

    const launchGameBtn = this.container.querySelector('#btn-launch-game-from-list');
    if (launchGameBtn) {
      launchGameBtn.addEventListener('click', () => {
        this.startGenreGame(this.state.activeGenreId);
      });
    }

    const searchInput = this.container.querySelector('#genre-word-search');
    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        this.state.searchQuery = e.target.value;
        this.renderWordListUI();
      });
    }

    this.container.querySelectorAll('.btn-switch-genre').forEach(btn => {
      btn.addEventListener('click', () => {
        this.state.activeGenreId = btn.dataset.genreId;
        this.state.searchQuery = '';
        this.renderWordListUI();
      });
    });

    this.container.querySelectorAll('.btn-play-word-audio').forEach(btn => {
      btn.addEventListener('click', () => {
        const word = btn.dataset.word;
        if (word) {
          SpeechService.speak(word, { rate: 0.9 });
        }
      });
    });
  }

  // ==========================================
  // 3. ジャンル別単語ゲーム開始
  // ==========================================
  static startGenreGame(genreId) {
    this.state.activeGenreId = genreId;
    const words = this.getGenreWords(genreId);
    if (!words || words.length < 4) {
      alert('このジャンルの単語数がゲームの開始要件（4語以上）に達していません。');
      return;
    }

    // 10問（または単語数上限）をシャッフル抽出
    const shuffled = shuffleArray([...words]);
    const count = Math.min(10, shuffled.length);
    this.state.gameQuestions = shuffled.slice(0, count);
    this.state.gameCurrentIndex = 0;
    this.state.gameScore = 0;
    this.state.gameCombo = 0;
    this.state.gameMaxCombo = 0;
    this.state.gameCorrectCount = 0;
    this.state.mistakes = [];
    this.state.gameResults = [];
    this.state.view = 'game';

    this.loadGameQuestion();
    this.renderUI();
  }

  static loadGameQuestion() {
    if (this.state.gameCurrentIndex >= this.state.gameQuestions.length) {
      this.finishGenreGame();
      return;
    }

    const qWord = this.state.gameQuestions[this.state.gameCurrentIndex];
    this.state.currentQuestion = qWord;
    this.state.hasAnswered = false;
    this.state.selectedChoice = null;
    this.state.isCorrect = false;

    // 出題形式：50%で「モンゴル語 ➜ 日本語」、50%で「日本語 ➜ モンゴル語」
    const isMnToJa = Math.random() > 0.35;
    this.state.questionType = isMnToJa ? 'mn_to_ja' : 'ja_to_mn';

    // 4択肢の作成（正解 ＋ 同ジャンル内のダミー3件）
    const allGenreWords = this.getGenreWords(this.state.activeGenreId);
    const otherWords = allGenreWords.filter(w => w.id !== qWord.id);
    const chosenDummies = shuffleArray(otherWords).slice(0, 3);

    const pool = [qWord, ...chosenDummies];
    const shuffledPool = shuffleArray(pool);

    this.state.gameChoices = shuffledPool.map(w => {
      const isCaution = typeof isPronunciationCautionWord === 'function' ? isPronunciationCautionWord(w) : false;
      return {
        word: w,
        text: isMnToJa ? w.japanese : w.mongolian,
        subText: isMnToJa ? '' : (isCaution && w.pronunciation ? `⚠️ [${w.pronunciation}]` : ''),
        isAnswer: w.id === qWord.id
      };
    });

    this.state.mascotMood = 'idle';
    this.state.mascotMessage = `第 ${this.state.gameCurrentIndex + 1} 問！がんばって！🐧`;

    // 自動音声再生（モンゴル語提示時）
    if (isMnToJa) {
      setTimeout(() => {
        try {
          SpeechService.speak(qWord.mongolian, { rate: 0.9 });
        } catch (_) {}
      }, 200);
    }
  }

  static renderGameUI() {
    const genre = GENRE_CONFIG.find(g => g.id === this.state.activeGenreId) || GENRE_CONFIG[0];
    const { currentQuestion, gameCurrentIndex, gameQuestions, gameChoices, gameScore, gameCombo, questionType, hasAnswered, selectedChoice, isCorrect, mascotMood, mascotMessage } = this.state;

    const isMnToJa = questionType === 'mn_to_ja';
    const progressPercent = Math.round(((gameCurrentIndex + 1) / gameQuestions.length) * 100);

    this.container.innerHTML = `
      <div class="animate-fade-in max-w-3xl mx-auto px-4 py-6 space-y-6">
        
        <!-- ゲームヘッダーバー -->
        <div class="flex items-center justify-between gap-3 bg-white p-3.5 rounded-2xl border border-slate-200 shadow-xs">
          <div class="flex items-center gap-2">
            <button type="button" id="btn-quit-genre-game" class="p-2 rounded-xl text-slate-500 hover:text-slate-800 hover:bg-slate-100 transition-colors" title="ゲームをやめる">
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
              </svg>
            </button>
            <div class="flex items-center gap-1.5 text-xs font-black text-slate-800">
              <span>${genre.icon}</span>
              <span>${genre.titleJa} ゲーム</span>
            </div>
          </div>

          <!-- スコア・コンボ -->
          <div class="flex items-center gap-2 text-xs">
            <div class="bg-amber-50 text-amber-900 border border-amber-300 px-3 py-1 rounded-full font-black flex items-center gap-1">
              <span>⚡</span>
              <span>${gameScore} pt</span>
              ${gameCombo >= 2 ? `<span class="bg-amber-400 text-slate-950 px-1.5 py-0.2 rounded-full text-[10px] font-bold">${gameCombo}連勝</span>` : ''}
            </div>
            <div class="text-slate-500 font-bold">
              ${gameCurrentIndex + 1} / ${gameQuestions.length}
            </div>
          </div>
        </div>

        <!-- 進捗バー -->
        <div class="w-full bg-slate-200 rounded-full h-2 overflow-hidden">
          <div class="bg-emerald-500 h-full rounded-full transition-all duration-300" style="width: ${progressPercent}%"></div>
        </div>

        <!-- 問題カード -->
        <div class="bg-white rounded-3xl border-2 border-slate-200 p-6 sm:p-8 text-center shadow-lg relative overflow-hidden">
          
          <div class="inline-flex items-center gap-1 text-xs font-bold text-slate-500 bg-slate-100 px-3 py-1 rounded-full mb-3">
            <span>${isMnToJa ? '🇲🇳 モンゴル語 ➜ 🇯🇵 日本語' : '🇯🇵 日本語 ➜ 🇲🇳 モンゴル語'}</span>
          </div>

          <!-- メイン問題文（ビジュアルイラスト付き） -->
          <div class="my-4">
            <div class="flex justify-center mb-3">
              ${(typeof getWordIllustrationHTML === 'function') ? getWordIllustrationHTML(currentQuestion, { size: 'xl' }) : ''}
            </div>
            ${isMnToJa ? `
              <h3 class="text-3xl sm:text-4xl md:text-5xl font-black text-slate-900 tracking-wide font-sans mb-2">
                ${currentQuestion.mongolian}
              </h3>
              ${(typeof isPronunciationCautionWord === 'function' && isPronunciationCautionWord(currentQuestion) && currentQuestion.pronunciation) ? `
                <div class="inline-block text-xs font-bold text-amber-700 bg-amber-50 px-3 py-1 rounded-full border border-amber-200 mb-3">
                  ⚠️ 読み注意: [ ${currentQuestion.pronunciation} ]
                </div>
              ` : '<div class="mb-2"></div>'}
              <button type="button" id="btn-audio-question" class="inline-flex items-center gap-1.5 text-xs bg-emerald-50 hover:bg-emerald-100 text-emerald-700 px-3.5 py-1.5 rounded-full font-bold transition-all border border-emerald-200 cursor-pointer">
                <span>🔊 発音を聴く</span>
              </button>
            ` : `
              <h3 class="text-3xl sm:text-4xl md:text-5xl font-black text-slate-900 tracking-wide font-sans mb-2">
                ${currentQuestion.japanese}
              </h3>
              <div class="text-xs text-slate-400 font-medium">
                品詞: ${currentQuestion.pos || '単語'}
              </div>
            `}
          </div>

          <!-- 4択選択肢 -->
          <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-6">
            ${gameChoices.map((c, idx) => {
              let btnClass = 'bg-slate-50 hover:bg-slate-100 text-slate-800 border-2 border-slate-200';
              if (hasAnswered) {
                if (c.isAnswer) {
                  btnClass = 'bg-emerald-500 text-white border-2 border-emerald-400 shadow-md font-black scale-102';
                } else if (selectedChoice === c && !isCorrect) {
                  btnClass = 'bg-rose-500 text-white border-2 border-rose-400 shadow-sm';
                } else {
                  btnClass = 'opacity-40 bg-slate-100 text-slate-400 border border-slate-200';
                }
              }

              return `
                <button type="button" class="btn-game-choice p-4 rounded-2xl text-left font-bold transition-all flex items-center justify-between ${btnClass} ${hasAnswered ? 'cursor-default pointer-events-none' : 'active:scale-98 cursor-pointer'}" data-choice-index="${idx}">
                  <div>
                    <div class="text-base sm:text-lg">${c.text}</div>
                    ${c.subText ? `<div class="text-xs text-amber-700 font-bold">${c.subText}</div>` : ''}
                  </div>
                  <span class="text-xs text-slate-400 font-mono">${idx + 1}</span>
                </button>
              `;
            }).join('')}
          </div>

          <!-- 回答後フィードバック -->
          ${hasAnswered ? `
            <div class="mt-6 p-4 rounded-2xl text-left border ${isCorrect ? 'bg-emerald-50 border-emerald-200 text-emerald-900' : 'bg-rose-50 border-rose-200 text-rose-900'}">
              <div class="flex items-center justify-between mb-2">
                <span class="font-black text-sm">
                  ${isCorrect ? '⭕ 正解！ амжилттай!' : '❌ おしい！'}
                </span>
                <button type="button" id="btn-next-game-q" class="px-5 py-2 rounded-xl bg-slate-900 text-white text-xs font-black hover:bg-slate-800 active:scale-95 transition-all shadow-md">
                  次へ進む →
                </button>
              </div>
              <div class="text-xs space-y-1">
                <div><strong>正解:</strong> <span class="correct-answer-text font-black text-slate-900">${currentQuestion.mongolian}</span> ${(typeof isPronunciationCautionWord === 'function' && isPronunciationCautionWord(currentQuestion) && currentQuestion.pronunciation) ? `<span class="text-amber-700 font-bold ml-1">⚠️ [${currentQuestion.pronunciation}]</span>` : ''} = ${currentQuestion.japanese}</div>
                ${currentQuestion.exampleMn ? `<div><strong>例文:</strong> ${currentQuestion.exampleMn} (${currentQuestion.exampleJa || ''})</div>` : ''}
                ${(typeof getWordEtymologyHTML === 'function') ? getWordEtymologyHTML(currentQuestion, currentQuestion.mongolian) : ''}
                ${(typeof getWordMnemonicHTML === 'function') ? getWordMnemonicHTML(currentQuestion, currentQuestion.mongolian) : ''}
                ${(typeof getSimilarWordDistinctionHTML === 'function') ? getSimilarWordDistinctionHTML(currentQuestion, currentQuestion.mongolian) : ''}
              </div>

              <!-- 選択肢に出た単語の全解説アコーディオン -->
              ${(typeof renderChoiceExplanationsHTML === 'function' && gameChoices && gameChoices.length > 0) ? renderChoiceExplanationsHTML(gameChoices.map(c => c.word), {
                expectedAnswer: isMnToJa ? currentQuestion.japanese : currentQuestion.mongolian,
                userAnswer: selectedChoice && selectedChoice.word ? (isMnToJa ? selectedChoice.word.japanese : selectedChoice.word.mongolian) : ''
              }) : ''}
            </div>
          ` : ''}

        </div>

        <!-- ペンギンマスコット リアクション -->
        <div class="bg-gradient-to-r from-sky-50 to-emerald-50 rounded-2xl p-4 border border-sky-200/70 flex items-center gap-3.5 shadow-2xs">
          <div class="shrink-0">
            ${PenguinMascot.getSvg({ mood: mascotMood, size: 50 })}
          </div>
          <div class="text-xs sm:text-sm font-bold text-slate-700">
            ${mascotMessage}
          </div>
        </div>

      </div>
    `;

    this.bindGameEvents();
  }

  static bindGameEvents() {
    const quitBtn = this.container.querySelector('#btn-quit-genre-game');
    if (quitBtn) {
      quitBtn.addEventListener('click', () => {
        if (confirm('ゲームを途中で終了してジャンル選択に戻りますか？')) {
          this.state.view = 'genre_select';
          this.renderUI();
        }
      });
    }

    const audioBtn = this.container.querySelector('#btn-audio-question');
    if (audioBtn && this.state.currentQuestion) {
      audioBtn.addEventListener('click', () => {
        SpeechService.speak(this.state.currentQuestion.mongolian, { rate: 0.9 });
      });
    }

    this.container.querySelectorAll('.btn-game-choice').forEach(btn => {
      btn.addEventListener('click', () => {
        if (this.state.hasAnswered) return;
        const idx = parseInt(btn.dataset.choiceIndex, 10);
        this.submitAnswer(idx);
      });
    });

    this.container.querySelectorAll('.btn-speak-choice-word').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const word = btn.getAttribute('data-word');
        if (word && typeof SpeechService !== 'undefined') {
          SpeechService.speak(word, { rate: 0.9 });
        }
      });
    });

    const nextBtn = this.container.querySelector('#btn-next-game-q');
    if (nextBtn) {
      nextBtn.addEventListener('click', () => {
        this.state.gameCurrentIndex++;
        this.loadGameQuestion();
        this.renderUI();
      });
    }
  }

  static submitAnswer(choiceIdx) {
    if (this.state.hasAnswered) return;
    this.state.hasAnswered = true;

    const chosen = this.state.gameChoices[choiceIdx];
    this.state.selectedChoice = chosen;
    const isCorrect = chosen && chosen.isAnswer;
    this.state.isCorrect = isCorrect;

    if (isCorrect) {
      this.state.gameCombo++;
      if (this.state.gameCombo > this.state.gameMaxCombo) {
        this.state.gameMaxCombo = this.state.gameCombo;
      }
      this.state.gameCorrectCount++;
      const pts = 10 + Math.min(this.state.gameCombo * 2, 20);
      this.state.gameScore += pts;

      this.state.mascotMood = 'happy';
      this.state.mascotMessage = `大正解！モグモグ！美味しいお魚ありがとう！🐟 (+${pts} pt)`;

      try {
        SoundEffects.playCorrect();
      } catch (_) {}

      // XP付与
      try {
        if (typeof GamificationService !== 'undefined' && typeof GamificationService.addXp === 'function') {
          GamificationService.addXp(10);
        }
      } catch (_) {}
    } else {
      this.state.gameCombo = 0;
      this.state.mascotMood = 'sad';
      this.state.mascotMessage = 'おしい！次はきっと正解できるよ！ファイト！🐧';

      try {
        SoundEffects.playWrong();
      } catch (_) {}

      this.state.mistakes.push(this.state.currentQuestion);

      try {
        const curQ = this.state.currentQuestion;
        const genre = this.getGenreById(this.state.selectedGenreId) || {};
        const isMnToJa = this.state.questionType === 'mn_to_ja';
        const userWord = chosen ? chosen.word : null;
        StorageService.recordMistake({
          question: `【ジャンル: ${genre.titleJa || '単語'}】${isMnToJa ? curQ.mongolian : curQ.japanese}`,
          userAnswer: userWord ? (isMnToJa ? userWord.japanese : userWord.mongolian) : '(未選択)',
          correctAnswer: isMnToJa ? curQ.japanese : (curQ.dictForm || curQ.mongolian),
          type: 'word',
          category: genre.titleJa || 'ジャンル単語',
          explanation: `${curQ.mongolian} = ${curQ.japanese}。${curQ.note || curQ.derivation || ''}`
        });
      } catch (err) {
        console.warn('Genre mistake recording error:', err);
      }
    }

    if (!this.state.gameResults) this.state.gameResults = [];
    this.state.gameResults.push({
      question: this.state.currentQuestion,
      questionType: this.state.questionType,
      choices: this.state.gameChoices ? this.state.gameChoices.map(c => c.word) : [],
      selectedChoice: chosen ? chosen.word : null,
      isCorrect: isCorrect
    });

    this.renderUI();
  }

  static finishGenreGame() {
    this.state.view = 'game_result';

    // ゲーム完了時ボーナスXP
    try {
      if (typeof GamificationService !== 'undefined' && typeof GamificationService.addXp === 'function') {
        const bonus = this.state.gameCorrectCount >= 8 ? 40 : 20;
        GamificationService.addXp(bonus);
      }
    } catch (_) {}

    this.renderUI();
  }

  // ==========================================
  // 4. ゲーム結果画面
  // ==========================================
  static renderGameResultUI() {
    const genre = GENRE_CONFIG.find(g => g.id === this.state.activeGenreId) || GENRE_CONFIG[0];
    const { gameScore, gameCorrectCount, gameQuestions, gameMaxCombo, mistakes } = this.state;
    const accuracy = Math.round((gameCorrectCount / gameQuestions.length) * 100);

    this.container.innerHTML = `
      <div class="animate-fade-in max-w-2xl mx-auto px-4 py-8 space-y-6">
        
        <div class="bg-white rounded-3xl border-2 border-slate-200 p-6 sm:p-8 text-center shadow-xl space-y-6">
          <div class="text-5xl">🎉</div>
          <div>
            <h2 class="text-2xl sm:text-3xl font-black text-slate-900">
              ゲーム終了！お疲れ様でした！
            </h2>
            <div class="text-xs font-bold text-slate-500 mt-1">
              ${genre.icon} ${genre.titleJa} 単語チャレンジ
            </div>
          </div>

          <!-- スコア・正解率バッジ -->
          <div class="grid grid-cols-3 gap-3 bg-slate-50 p-4 rounded-2xl border border-slate-100">
            <div>
              <div class="text-xs font-bold text-slate-500">獲得スコア</div>
              <div class="text-2xl font-black text-amber-600">${gameScore} pt</div>
            </div>
            <div>
              <div class="text-xs font-bold text-slate-500">正解数</div>
              <div class="text-2xl font-black text-emerald-600">${gameCorrectCount} / ${gameQuestions.length}</div>
            </div>
            <div>
              <div class="text-xs font-bold text-slate-500">最大連勝</div>
              <div class="text-2xl font-black text-indigo-600">${gameMaxCombo} 連勝</div>
            </div>
          </div>

          <!-- 間違えた単語の復習リスト -->
          ${mistakes.length > 0 ? `
            <!-- 間違いノート自動保存通知バナー ＆ 直行ボタン -->
            <div class="p-3.5 bg-rose-50 dark:bg-rose-950/50 border border-rose-200 dark:border-rose-800 rounded-2xl flex flex-col sm:flex-row items-center justify-between gap-3 shadow-2xs text-left">
              <div class="text-xs text-rose-800 dark:text-rose-200 font-bold flex items-center gap-1.5">
                <span class="text-base">🔥</span>
                <span>間違えた <strong>${mistakes.length}</strong> 語を「間違いノート」に自動保存しました</span>
              </div>
              <button type="button" id="btn-goto-mistakes-from-genre" class="w-full sm:w-auto px-4 py-2 bg-gradient-to-r from-rose-500 to-amber-500 hover:from-rose-600 hover:to-amber-600 text-white font-black rounded-xl text-xs shadow-xs transition-all flex items-center justify-center gap-1.5 cursor-pointer shrink-0">
                <span>間違いノートで特訓</span>
                <span>→</span>
              </button>
            </div>

            <div class="text-left space-y-2 pt-2">
              <h4 class="text-xs font-black text-slate-700 flex items-center gap-1.5">
                <span>📝 要復習単語 (${mistakes.length}語):</span>
              </h4>
              <div class="space-y-1.5 max-h-48 overflow-y-auto pr-1">
                ${mistakes.map(w => `
                  <div class="flex items-center justify-between p-2.5 bg-rose-50/70 border border-rose-200 rounded-xl text-xs">
                    <div>
                      <span class="font-black text-slate-900 font-sans">${w.mongolian}</span>
                      ${(typeof isPronunciationCautionWord === 'function' && isPronunciationCautionWord(w) && w.pronunciation) ? `<span class="text-amber-700 font-bold ml-1.5">⚠️ [${w.pronunciation}]</span>` : ''}
                    </div>
                    <span class="font-bold text-slate-700">${w.japanese}</span>
                  </div>
                `).join('')}
              </div>
            </div>
          ` : `
            <div class="p-3 bg-emerald-50 border border-emerald-200 rounded-2xl text-xs font-black text-emerald-800">
              🌟 パーフェクト！このジャンルの単語は完璧です！
            </div>
          `}

          <!-- 出題問題と選択肢の全解説アコーディオンリスト -->
          ${(this.state.gameResults && this.state.gameResults.length > 0) ? `
            <div class="text-left space-y-3 pt-2">
              <h4 class="text-xs font-black text-slate-700 dark:text-slate-200 flex items-center gap-1.5">
                <span>📋</span> 出題問題と選択肢の全解説 (${this.state.gameResults.length}問):
              </h4>
              <div class="space-y-3 max-h-96 overflow-y-auto pr-1">
                ${this.state.gameResults.map((res, qIdx) => {
                  const qWord = res.question;
                  const isMnToJa = res.questionType === 'mn_to_ja';
                  return `
                    <div class="p-3 bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 space-y-2 text-xs shadow-2xs">
                      <div class="flex items-start justify-between gap-2">
                        <div class="space-y-1">
                          <div class="flex items-center gap-2">
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${res.isCorrect ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950/80 dark:text-emerald-300' : 'bg-rose-100 text-rose-800 dark:bg-rose-950/80 dark:text-rose-300'}">
                              第${qIdx + 1}問: ${res.isCorrect ? '⭕ 正解' : '❌ 不正解'}
                            </span>
                            <span class="font-black text-slate-900 dark:text-white cyrillic-text text-sm">${qWord.mongolian}</span>
                            ${qWord.pronunciation ? `<span class="text-[11px] text-amber-600 dark:text-amber-400 font-bold">[${qWord.pronunciation}]</span>` : ''}
                          </div>
                          <div class="text-slate-600 dark:text-slate-300 font-bold">
                            意味: <span class="text-emerald-700 dark:text-emerald-400">${qWord.japanese}</span>
                          </div>
                          ${!res.isCorrect && res.selectedChoice ? `
                            <div class="text-rose-600 dark:text-rose-400 font-bold text-[11px]">
                              あなたの回答: <span class="line-through">${isMnToJa ? res.selectedChoice.japanese : res.selectedChoice.mongolian}</span>
                            </div>
                          ` : ''}
                        </div>
                        <button type="button" class="btn-speak-choice-word p-1.5 rounded-lg bg-slate-100 dark:bg-slate-700 text-slate-500 hover:text-emerald-700 dark:text-slate-300 cursor-pointer" data-word="${qWord.mongolian}" title="発音を聞く">
                          🔊
                        </button>
                      </div>

                      <!-- 4択の全解説アコーディオン -->
                      ${(typeof renderChoiceExplanationsHTML === 'function' && res.choices && res.choices.length > 0) ? renderChoiceExplanationsHTML(res.choices, {
                        expectedAnswer: isMnToJa ? qWord.japanese : qWord.mongolian,
                        userAnswer: res.selectedChoice ? (isMnToJa ? res.selectedChoice.japanese : res.selectedChoice.mongolian) : ''
                      }) : ''}
                    </div>
                  `;
                }).join('')}
              </div>
            </div>
          ` : ''}

          <!-- アクションボタン -->
          <div class="flex flex-col sm:flex-row items-center justify-center gap-3 pt-2">
            <button type="button" id="btn-replay-genre-game" class="w-full sm:w-auto px-6 py-2.5 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 hover:to-teal-600 text-white font-black text-sm shadow-md active:scale-95 transition-all">
              🔄 もう一度挑戦
            </button>
            <button type="button" id="btn-result-to-wordlist" class="w-full sm:w-auto px-5 py-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-sm transition-all">
              📖 単語帳で復習
            </button>
            <button type="button" id="btn-result-to-genres" class="w-full sm:w-auto px-5 py-2.5 rounded-xl border border-slate-200 hover:bg-slate-50 text-slate-600 font-bold text-sm transition-all">
              🏷️ 他のジャンルへ
            </button>
          </div>

        </div>

      </div>
    `;

    this.bindResultEvents();
  }

  static bindResultEvents() {
    this.container.querySelectorAll('.btn-speak-choice-word').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const word = btn.getAttribute('data-word');
        if (word && typeof SpeechService !== 'undefined') {
          SpeechService.speak(word, { rate: 0.9 });
        }
      });
    });
    const replayBtn = this.container.querySelector('#btn-replay-genre-game');
    if (replayBtn) {
      replayBtn.addEventListener('click', () => {
        this.startGenreGame(this.state.activeGenreId);
      });
    }

    const gotoMistakesBtn = this.container.querySelector('#btn-goto-mistakes-from-genre');
    if (gotoMistakesBtn) {
      gotoMistakesBtn.addEventListener('click', () => {
        if (this.onNavigate) {
          if (typeof ReviewNotebookComponent !== 'undefined') {
            ReviewNotebookComponent.state.view = 'list';
            ReviewNotebookComponent.state.filterType = 'all';
          }
          this.onNavigate('review');
        }
      });
    }

    const wordlistBtn = this.container.querySelector('#btn-result-to-wordlist');
    if (wordlistBtn) {
      wordlistBtn.addEventListener('click', () => {
        this.state.view = 'word_list';
        this.renderUI();
      });
    }

    const genresBtn = this.container.querySelector('#btn-result-to-genres');
    if (genresBtn) {
      genresBtn.addEventListener('click', () => {
        this.state.view = 'genre_select';
        this.renderUI();
      });
    }
  }
}

if (typeof window !== 'undefined') {
  window.GenreWordMasterComponent = GenreWordMasterComponent;
}


// === js/components/SpellingGame.js ===
// スペリングゲームコンポーネント（水色オーシャン・レーザー魚キャッチアクション）
// お魚の中に和訳が書かれて上から降ってくる！落ち切る前にスペルを入力してレーザーで打ち落とすとペンギンが食べる！
// ※打鍵ごとの全画面再描画を完全撤廃し、インプレース部分更新によりチカチカ・点滅を100%防止







class SpellingGameComponent {
  static container = null;
  static onNavigate = null;
  static returnTarget = 'word_game';
  static keydownHandler = null;
  static fallInterval = null;

  static state = {
    view: 'playing', // 'playing' | 'result'
    mode: 'tile_arrange', // 'tile_arrange' | 'free_type'
    category: 'all',
    
    questions: [],
    currentIndex: 0,
    currentWord: null,
    targetLetters: [],
    
    // タイル並べ替え用
    candidateTiles: [], // { id, char, isUsed }
    placedLetters: [],  // { tileId, char }
    
    // 自力入力用
    typedLetters: [],
    
    // ゲーム進行・満腹度
    score: 0,
    combo: 0,
    maxCombo: 0,
    fishFedCount: 0,
    fullness: 0, // 0 - 5 (5匹で 100% 満腹フィーバー)
    todayTotalFed: 0,
    
    // 魚の落下・レーザーアクション
    fallProgress: 0, // 0% (上) 〜 100% (下・逃げられる)
    fallDurationSec: 15, // 1問あたりの落下秒数
    isLaserShooting: false,
    isFishHit: false,
    isFishCaught: false,
    isFishEscaped: false,
    isPaused: false,
    
    // ペンギンマスコット
    mascotMood: 'idle',
    mascotMessage: 'お魚が落ちてくるよ！急いでスペルを撃ち落とそう！🐟⚡',
    
    // 状態管理
    hasAnswered: false,
    isMistake: false,
    isFeeding: false,
    hintsUsed: 0,
    
    // 履歴
    answeredLog: []
  };

  static render(container, onNavigate) {
    this.container = container;
    this.onNavigate = onNavigate;
    this.initGame();
  }

  // ==========================================
  // ゲーム初期化 ＆ 問題選出
  // ==========================================
  static initGame(preserveSettings = false) {
    this.stopFallTimer();
    if (!preserveSettings) {
      this.state.score = 0;
      this.state.combo = 0;
      this.state.maxCombo = 0;
      this.state.fishFedCount = 0;
      this.state.fullness = 0;
      this.state.answeredLog = [];
    }
    
    this.loadTodayFedCount();
    this.prepareQuestions();
    this.state.currentIndex = 0;
    this.state.view = 'playing';
    this.loadCurrentWord();
    this.renderUI();
  }

  static loadTodayFedCount() {
    try {
      const today = new Date().toISOString().slice(0, 10);
      const saved = localStorage.getItem('mongol_spelling_fed_' + today);
      this.state.todayTotalFed = saved ? parseInt(saved, 10) : 0;
    } catch (_) {
      this.state.todayTotalFed = 0;
    }
  }

  static saveTodayFedCount() {
    try {
      const today = new Date().toISOString().slice(0, 10);
      localStorage.setItem('mongol_spelling_fed_' + today, String(this.state.todayTotalFed));
    } catch (_) {}
  }

  static prepareQuestions() {
    const rawVocab = StorageService.getVocabulary();
    let pool = rawVocab.filter(w => {
      if (!w.mongolian || !w.japanese) return false;
      const clean = w.mongolian.trim().toLowerCase().replace(/[.,?!/\\~]/g, '');
      return clean.length >= 2 && clean.length <= 10 && !clean.includes(' ');
    });

    if (pool.length < 5) {
      pool = rawVocab.filter(w => w.mongolian && w.japanese);
    }

    const shuffled = shuffleArray([...pool]);
    this.state.questions = shuffled.slice(0, 10);
    if (this.state.questions.length === 0) {
      this.state.questions = [
        { mongolian: 'сайн', japanese: '良い、こんにちは', pos: '形容詞' },
        { mongolian: 'ном', japanese: '本', pos: '名詞' },
        { mongolian: 'ус', japanese: '水', pos: '名詞' },
        { mongolian: 'аш', japanese: '利益、恩恵', pos: '名詞' },
        { mongolian: 'морь', japanese: '馬', pos: '名詞' }
      ];
    }
  }

  static loadCurrentWord() {
    this.stopFallTimer();
    const word = this.state.questions[this.state.currentIndex];
    if (!word) {
      this.showResult();
      return;
    }

    this.state.currentWord = word;
    const cleanWord = word.mongolian.trim().toLowerCase().replace(/[.,?!/\\~]/g, '');
    this.state.targetLetters = cleanWord.split('');
    this.state.placedLetters = [];
    this.state.typedLetters = [];
    this.state.hasAnswered = false;
    this.state.isMistake = false;
    this.state.isFeeding = false;
    this.state.isLaserShooting = false;
    this.state.isFishHit = false;
    this.state.isFishCaught = false;
    this.state.isFishEscaped = false;
    this.state.hintsUsed = 0;
    this.state.fallProgress = 0;
    this.state.mascotMood = this.state.combo > 2 ? 'happy' : 'idle';
    this.state.mascotMessage = 'お魚が落ちてくるよ！急いでスペルを撃ち落とそう！🐟⚡';

    // 候補タイルの生成（正解文字 ＋ ダミー文字3〜4文字）
    const dummyPool = ['а', 'э', 'и', 'о', 'у', 'ө', 'ү', 'н', 'м', 'л', 'р', 'с', 'т', 'б', 'в', 'г', 'д', 'х', 'й', 'ж', 'з'];
    const neededDummies = Math.max(3, 10 - this.state.targetLetters.length);
    const chosenDummies = [];
    for (let i = 0; i < neededDummies; i++) {
      const randChar = dummyPool[Math.floor(Math.random() * dummyPool.length)];
      chosenDummies.push(randChar);
    }

    const allChars = [...this.state.targetLetters, ...chosenDummies];
    const shuffledChars = shuffleArray(allChars);

    this.state.candidateTiles = shuffledChars.map((ch, idx) => ({
      id: `tile_${idx}_${ch}`,
      char: ch,
      isUsed: false
    }));

    // 落下タイマー開始
    this.startFallTimer();
  }

  // ==========================================
  // 魚の落下タイマー
  // ==========================================
  static startFallTimer() {
    this.stopFallTimer();
    const durationMs = this.state.fallDurationSec * 1000;
    const stepMs = 60;
    const stepPct = (stepMs / durationMs) * 100;

    this.fallInterval = setInterval(() => {
      if (this.state.isPaused || this.state.hasAnswered || this.state.view !== 'playing') {
        return;
      }

      this.state.fallProgress += stepPct;
      if (this.state.fallProgress >= 100) {
        this.state.fallProgress = 100;
        this.stopFallTimer();
        this.onFishEscaped();
      } else {
        this.updateFishDOM();
      }
    }, stepMs);
  }

  static stopFallTimer() {
    if (this.fallInterval) {
      clearInterval(this.fallInterval);
      this.fallInterval = null;
    }
  }

  static updateFishDOM() {
    const fishEl = this.container?.querySelector('#falling-fish-box');
    const barEl = this.container?.querySelector('#fall-progress-bar');
    if (fishEl) {
      const topPos = 8 + (this.state.fallProgress * 0.60);
      fishEl.style.top = `${topPos}%`;
    }
    if (barEl) {
      const remainPct = Math.max(0, 100 - this.state.fallProgress);
      barEl.style.width = `${remainPct}%`;
      if (remainPct < 25) {
        barEl.className = 'h-full bg-red-500 transition-none';
      } else if (remainPct < 50) {
        barEl.className = 'h-full bg-amber-400 transition-none';
      } else {
        barEl.className = 'h-full bg-emerald-400 transition-none';
      }
    }
  }

  // ==========================================
  // UIレンダリング（全画面再描画：問題切替時やモード切替時のみ）
  // ==========================================
  static renderUI() {
    if (!this.container) return;
    if (this.state.view === 'result') {
      this.renderResultUI();
      return;
    }

    const { currentWord, targetLetters, placedLetters, typedLetters, candidateTiles, mode, score, combo, fullness, fishFedCount, todayTotalFed, mascotMood, mascotMessage, isLaserShooting, isFishHit, isFishCaught, isFishEscaped } = this.state;
    const isArrange = mode === 'tile_arrange';
    const currentLetters = isArrange ? placedLetters.map(p => p.char) : typedLetters;

    // チカチカ防止：最外層の animate-fade-in を完全撤廃
    this.container.innerHTML = `
      <div class="max-w-4xl mx-auto px-3 sm:px-4 py-4 space-y-4">
        
        <!-- ナビゲーション・ヘッダーバー -->
        <div class="flex flex-wrap items-center justify-between gap-3 bg-white p-3 rounded-2xl border border-slate-200 shadow-xs">
          <div class="flex items-center gap-2">
            <button type="button" id="btn-spelling-back" class="p-2 rounded-xl text-slate-500 hover:text-slate-800 hover:bg-slate-100 transition-colors" title="ホームへ戻る">
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path>
              </svg>
            </button>
            <h2 class="text-base sm:text-lg font-black text-slate-800 flex items-center gap-1.5">
              <span>🐟⚡</span>
              <span>モンゴル語スペルシューター</span>
            </h2>
          </div>

          <!-- モード切り替えピル -->
          <div class="flex items-center bg-slate-100 p-1 rounded-xl text-xs font-bold">
            <button type="button" id="btn-mode-arrange" class="px-3 py-1.5 rounded-lg ${
              isArrange ? 'bg-amber-500 text-white shadow-xs' : 'text-slate-600 hover:text-slate-900'
            }">
              🔤 候補タイルあり（タップ / 打鍵）
            </button>
            <button type="button" id="btn-mode-free" class="px-3 py-1.5 rounded-lg ${
              !isArrange ? 'bg-indigo-600 text-white shadow-xs' : 'text-slate-600 hover:text-slate-900'
            }">
              ⌨️ 候補なし自力入力
            </button>
          </div>

          <!-- スコア・ご飯ステータス -->
          <div class="flex items-center gap-2 text-xs">
            <div id="spelling-score-box" class="flex items-center gap-1 bg-amber-50 text-amber-900 border border-amber-300 px-2.5 py-1 rounded-full font-black">
              <span>⚡</span>
              <span>${score} pt</span>
              ${combo >= 2 ? `<span class="bg-amber-400 text-slate-950 px-1.5 py-0.2 rounded-full text-[10px] font-bold">${combo}コンボ</span>` : ''}
            </div>
            <div class="flex items-center gap-1 bg-sky-50 text-sky-900 border border-sky-300 px-2.5 py-1 rounded-full font-black" title="本日あげたご飯の数">
              <span>🐟</span>
              <span>× ${fishFedCount}匹</span>
              <span class="text-[10px] text-sky-600 hidden sm:inline">(本日計 ${todayTotalFed})</span>
            </div>
          </div>
        </div>

        <!-- 水色オーシャン・ゲームステージ -->
        <div class="relative bg-gradient-to-b from-sky-400 via-cyan-500 to-blue-600 rounded-3xl p-4 sm:p-7 border-2 border-sky-300 shadow-xl overflow-hidden min-h-[520px] text-slate-900 flex flex-col justify-between select-none">
          
          <!-- 水中の気泡エフェクト（CSSドット） -->
          <div class="absolute inset-0 pointer-events-none opacity-30 bg-[radial-gradient(#ffffff_2px,transparent_2px)] [background-size:32px_32px]"></div>
          
          <!-- 海面の揺らめきハイライト -->
          <div class="absolute top-0 left-0 right-0 h-12 bg-gradient-to-b from-white/30 to-transparent pointer-events-none"></div>

          <!-- 制限時間（落下ゲージ）バー -->
          <div class="relative z-10 w-full max-w-md mx-auto bg-black/25 backdrop-blur-xs rounded-full p-1 border border-white/40 shadow-xs mb-2">
            <div class="flex items-center justify-between text-[11px] font-black text-white px-2 mb-0.5">
              <span class="flex items-center gap-1">⏱️ 落下ゲージ: 落ち切る前に撃ち落とそう！</span>
              <span id="fall-seconds-text">${Math.max(0, Math.ceil(this.state.fallDurationSec * (1 - this.state.fallProgress / 100)))} 秒</span>
            </div>
            <div class="w-full bg-white/20 h-2.5 rounded-full overflow-hidden">
              <div id="fall-progress-bar" class="h-full bg-emerald-400 transition-none" style="width: ${Math.max(0, 100 - this.state.fallProgress)}%;"></div>
            </div>
          </div>

          <!-- レーザー光線エフェクト（正解時に下から魚へビシューン！） -->
          ${isLaserShooting ? `
            <div class="laser-beam absolute left-1/2 bottom-24 -translate-x-1/2 w-3 sm:w-4 bg-gradient-to-t from-cyan-200 via-white to-amber-300 rounded-full shadow-[0_0_25px_#ffffff] z-30 pointer-events-none transition-none" style="height: 60%;"></div>
          ` : ''}

          <!-- 上から降ってくるお魚カプセル（魚の中に和訳！！） -->
          <div id="falling-fish-box" class="absolute left-1/2 -translate-x-1/2 z-20 transition-none flex flex-col items-center" style="top: ${8 + (this.state.fallProgress * 0.60)}%;">
            
            <div class="relative flex items-center justify-center filter drop-shadow-xl ${isFishHit ? 'scale-125 rotate-12' : ''} ${isFishCaught ? 'scale-0 translate-y-32 opacity-0' : ''}">
              
              <!-- お魚ボディ（和訳内蔵） -->
              <div class="relative bg-gradient-to-r from-amber-300 via-orange-400 to-amber-400 text-slate-950 px-5 sm:px-7 py-3 rounded-full border-2 border-white shadow-2xl flex items-center gap-3">
                <div class="absolute -right-3 sm:-right-4 top-1/2 -translate-y-1/2 w-0 h-0 border-y-8 border-y-transparent border-r-12 border-r-orange-400"></div>
                
                <span class="text-2xl sm:text-3xl">🐟</span>
                
                <div class="text-center">
                  <div class="flex items-center justify-center gap-1.5 mb-0.5">
                    <span class="text-[10px] font-black bg-white/90 text-slate-800 px-2 py-0.2 rounded-full border border-orange-200">
                      ${currentWord.pos || '単語'}
                    </span>
                    <span class="text-[10px] font-bold text-white/95 drop-shadow-xs">
                      第 ${this.state.currentIndex + 1} / ${this.state.questions.length} 問
                    </span>
                  </div>
                  <!-- 和訳テキスト -->
                  <h3 class="text-lg sm:text-2xl md:text-3xl font-black text-slate-950 tracking-wide drop-shadow-xs">
                    ${currentWord.japanese}
                  </h3>
                </div>

                <!-- 音声ボタン -->
                <button type="button" id="btn-audio-prompt" class="p-1.5 bg-white/80 hover:bg-white text-orange-950 rounded-full shadow-xs" title="発音を聴く">
                  🔊
                </button>
              </div>

              <!-- 被弾エフェクト -->
              ${isFishHit ? `
                <div class="absolute inset-0 flex items-center justify-center text-3xl font-black text-yellow-200 drop-shadow-[0_0_15px_#fde047] z-30">
                  💥 HIT!!
                </div>
              ` : ''}

              <!-- 逃げられたエフェクト -->
              ${isFishEscaped ? `
                <div class="absolute -top-7 text-xs font-black bg-rose-600 text-white px-3 py-1 rounded-full shadow-lg">
                  ポチャッ… 逃げられた！
                </div>
              ` : ''}
            </div>
          </div>

          <!-- ステージ中央下部：入力文字スロット（レーザー照準器デザイン） -->
          <div class="relative z-10 w-full max-w-2xl mx-auto mt-40 sm:mt-48 mb-2">
            
            <div class="bg-black/30 backdrop-blur-md rounded-2xl p-4 border border-white/30 shadow-lg text-center space-y-3">
              <div class="text-[11px] font-black text-sky-200 tracking-wider flex items-center justify-center gap-1">
                <span>🎯 スペルを入力してレーザーで打ち落とそう！</span>
              </div>

              <!-- 文字スロット（DOM部分更新対応） -->
              <div id="spelling-slots-container" class="flex flex-wrap items-center justify-center gap-1.5 sm:gap-2.5 min-h-[58px]">
                ${targetLetters.map((expectedChar, idx) => {
                  const placed = currentLetters[idx];
                  const hasChar = !!placed;
                  
                  let slotColor = 'bg-white/20 border-white/40 text-white';
                  if (hasChar) {
                    slotColor = 'bg-gradient-to-b from-amber-300 to-yellow-400 border-yellow-200 text-slate-950 font-black shadow-md';
                  }

                  return `
                    <div class="spelling-slot relative w-10 h-12 sm:w-12 sm:h-14 rounded-xl border-2 flex items-center justify-center text-xl sm:text-2xl font-mono ${slotColor} ${
                      isArrange && hasChar ? 'cursor-pointer hover:bg-rose-400 hover:text-white' : ''
                    }" data-index="${idx}" title="${isArrange && hasChar ? 'タップして取り消す' : ''}">
                      <span>${placed || ''}</span>
                      <div class="slot-underline absolute bottom-1 w-4 h-0.5 bg-white/40 rounded-full" style="display: ${hasChar ? 'none' : 'block'};"></div>
                    </div>
                  `;
                }).join('')}
              </div>

              <!-- 入力モード別操作エリア -->
              ${isArrange ? `
                <div class="pt-2 border-t border-white/20 space-y-2.5">
                  <div class="text-xs font-bold text-sky-100 flex items-center justify-between px-1">
                    <span>✨ 文字タイルをタップ（またはキーボード打鍵）:</span>
                    <span id="tiles-remaining-count" class="text-[11px] text-white/80">${candidateTiles.filter(t => !t.isUsed).length} 文字残り</span>
                  </div>

                  <!-- 候補タイル群 -->
                  <div id="candidate-tiles-container" class="flex flex-wrap items-center justify-center gap-1.5 sm:gap-2 min-h-[50px]">
                    ${candidateTiles.map(tile => `
                      <button type="button" class="candidate-tile w-10 h-11 sm:w-11 sm:h-12 rounded-xl text-lg sm:text-xl font-black font-mono border-2 ${
                        tile.isUsed 
                          ? 'bg-black/30 border-transparent text-white/20 cursor-not-allowed' 
                          : 'bg-amber-400 hover:bg-amber-300 active:scale-95 border-amber-200 text-slate-950 shadow-md'
                      }" data-tile-id="${tile.id}" data-char="${tile.char}" ${tile.isUsed ? 'disabled' : ''}>
                        ${tile.char}
                      </button>
                    `).join('')}
                  </div>

                  <!-- サブボタン群 -->
                  <div class="flex items-center justify-center gap-2 pt-1">
                    <button type="button" id="btn-backspace" class="px-3 py-1.5 rounded-xl bg-white/20 hover:bg-white/30 text-white text-xs font-bold border border-white/30 flex items-center gap-1">
                      <span>⌫</span> 1文字戻す
                    </button>
                    <button type="button" id="btn-reset-slots" class="px-3 py-1.5 rounded-xl bg-white/20 hover:bg-white/30 text-white text-xs font-bold border border-white/30 flex items-center gap-1">
                      <span>🔄</span> リセット
                    </button>
                    <button type="button" id="btn-shuffle-tiles" class="px-3 py-1.5 rounded-xl bg-white/20 hover:bg-white/30 text-white text-xs font-bold border border-white/30 flex items-center gap-1">
                      <span>🔀</span> シャッフル
                    </button>
                    <button type="button" id="btn-hint" class="px-3.5 py-1.5 rounded-xl bg-gradient-to-r from-amber-400 to-yellow-400 hover:from-amber-300 hover:to-yellow-300 text-slate-950 text-xs font-black shadow-xs flex items-center gap-1">
                      <span>💡</span> ヒント (1文字開く)
                    </button>
                  </div>
                </div>
              ` : `
                <!-- 自力入力モード -->
                <div class="pt-2 border-t border-white/20 space-y-2">
                  <div class="text-xs font-bold text-sky-100">
                    ⌨️ PCキーボードでそのまま打鍵（ローマ字・キリル両対応）または下記バーをタップ
                  </div>
                  <div class="flex flex-wrap justify-center gap-1 max-w-lg mx-auto">
                    ${SPECIAL_CYRILLIC_BAR.map(c => `
                      <button type="button" class="btn-cyr-key px-2.5 py-1 bg-white/20 hover:bg-white/30 text-white font-mono font-bold text-sm rounded-lg border border-white/30" data-char="${c}">
                        ${c}
                      </button>
                    `).join('')}
                    <button type="button" id="btn-free-backspace" class="px-3 py-1 bg-white/20 hover:bg-white/30 text-white text-xs font-bold rounded-lg border border-white/30">
                      ⌫ 戻す
                    </button>
                  </div>
                </div>
              `}
            </div>
          </div>

          <!-- ステージ下部：ペンギンマスコット ＆ 満腹度バー（待機＆食事エリア） -->
          <div class="relative z-10 bg-black/40 backdrop-blur-md rounded-2xl p-3 sm:p-4 border border-white/30 text-white flex flex-col sm:flex-row items-center justify-between gap-3 shadow-lg">
            
            <!-- 満腹度ゲージ (0〜5匹) -->
            <div class="w-full sm:w-1/2 space-y-1">
              <div class="flex items-center justify-between text-xs font-extrabold text-sky-200">
                <span class="flex items-center gap-1">
                  <span>🧭</span> ペンギンの満腹度
                </span>
                <span id="penguin-fullness-text" class="text-amber-300 font-mono text-sm">${fullness * 20}% (${fullness}/5匹)</span>
              </div>
              <div class="w-full bg-white/20 h-3 rounded-full overflow-hidden p-0.5 border border-white/30">
                <div id="penguin-fullness-bar" class="bg-gradient-to-r from-amber-400 via-emerald-400 to-teal-300 h-full rounded-full transition-all duration-300" style="width: ${fullness * 20}%"></div>
              </div>
              <p class="text-[10px] text-white/70">
                5匹食べると【満腹フィーバー】突入！ボーナス +50 XP 獲得！
              </p>
            </div>

            <!-- ペンギンマスコットのアニメーションとメッセージ -->
            <div class="flex items-center gap-3 w-full sm:w-1/2 justify-center sm:justify-end">
              <div class="relative w-14 h-14 shrink-0 flex items-center justify-center">
                <div id="penguin-svg-wrapper" class="${isFishCaught ? 'scale-125' : ''}">
                  ${PenguinMascot.getSvg(mascotMood, 54)}
                </div>
                ${isFishCaught ? `
                  <div class="absolute -top-3 -right-2 text-lg">😋🐟</div>
                ` : ''}
              </div>
              <div class="text-left">
                <div id="penguin-mascot-msg" class="text-xs font-bold text-amber-200 leading-snug">
                  ${mascotMessage}
                </div>

              </div>
            </div>
          </div>
        </div>
      </div>
    `;

    this.bindEvents();
    this.bindKeyboardInput();
  }

  // ==========================================
  // チカチカゼロ：スロットとタイルのインプレース部分更新
  // ==========================================
  static updateSlotsAndTilesOnly() {
    if (!this.container) return;
    const { placedLetters, typedLetters, candidateTiles, mode, targetLetters } = this.state;
    const isArrange = mode === 'tile_arrange';
    const currentLetters = isArrange ? placedLetters.map(p => p.char) : typedLetters;

    // 1. スロット文字と外観の部分更新
    const slots = this.container.querySelectorAll('.spelling-slot');
    slots.forEach((slot, idx) => {
      const char = currentLetters[idx] || '';
      const span = slot.querySelector('span');
      if (span) span.textContent = char;

      const underline = slot.querySelector('.slot-underline');
      if (char) {
        slot.className = `spelling-slot relative w-10 h-12 sm:w-12 sm:h-14 rounded-xl border-2 flex items-center justify-center text-xl sm:text-2xl font-mono bg-gradient-to-b from-amber-300 to-yellow-400 border-yellow-200 text-slate-950 font-black shadow-md ${
          isArrange ? 'cursor-pointer hover:bg-rose-400 hover:text-white' : ''
        }`;
        if (underline) underline.style.display = 'none';
      } else {
        slot.className = 'spelling-slot relative w-10 h-12 sm:w-12 sm:h-14 rounded-xl border-2 flex items-center justify-center text-xl sm:text-2xl font-mono bg-white/20 border-white/40 text-white';
        if (underline) underline.style.display = 'block';
      }
    });

    // 2. 候補タイルの使用状態の部分更新
    if (isArrange) {
      const tileBtns = this.container.querySelectorAll('.candidate-tile');
      tileBtns.forEach(btn => {
        const tileId = btn.dataset.tileId;
        const tileData = candidateTiles.find(t => t.id === tileId);
        if (tileData) {
          if (tileData.isUsed) {
            btn.disabled = true;
            btn.className = 'candidate-tile w-10 h-11 sm:w-11 sm:h-12 rounded-xl text-lg sm:text-xl font-black font-mono border-2 bg-black/30 border-transparent text-white/20 cursor-not-allowed';
          } else {
            btn.disabled = false;
            btn.className = 'candidate-tile w-10 h-11 sm:w-11 sm:h-12 rounded-xl text-lg sm:text-xl font-black font-mono border-2 bg-amber-400 hover:bg-amber-300 active:scale-95 border-amber-200 text-slate-950 shadow-md';
          }
        }
      });

      const remainEl = this.container.querySelector('#tiles-remaining-count');
      if (remainEl) {
        remainEl.textContent = `${candidateTiles.filter(t => !t.isUsed).length} 文字残り`;
      }
    }
  }

  // ==========================================
  // イベントリスナー登録
  // ==========================================
  static bindEvents() {
    if (!this.container) return;

    // 戻るボタン
    const btnBack = this.container.querySelector('#btn-spelling-back');
    if (btnBack) {
      btnBack.addEventListener('click', () => {
        this.stopFallTimer();
        if (this.onNavigate) this.onNavigate(this.returnTarget || 'word_game');
      });
    }

    // 音声発音ボタン
    const btnAudio = this.container.querySelector('#btn-audio-prompt');
    if (btnAudio) {
      btnAudio.addEventListener('click', (e) => {
        e.stopPropagation();
        if (this.state.currentWord?.mongolian) {
          SpeechService.speak(this.state.currentWord.mongolian, { rate: 0.9 });
        }
      });
    }

    // モード切り替え
    const btnModeArrange = this.container.querySelector('#btn-mode-arrange');
    const btnModeFree = this.container.querySelector('#btn-mode-free');
    if (btnModeArrange) {
      btnModeArrange.addEventListener('click', () => {
        if (this.state.mode !== 'tile_arrange') {
          this.state.mode = 'tile_arrange';
          this.loadCurrentWord();
          this.renderUI();
        }
      });
    }
    if (btnModeFree) {
      btnModeFree.addEventListener('click', () => {
        if (this.state.mode !== 'free_type') {
          this.state.mode = 'free_type';
          this.loadCurrentWord();
          this.renderUI();
        }
      });
    }

    // 候補タイルのクリック
    const tiles = this.container.querySelectorAll('.candidate-tile');
    tiles.forEach(t => {
      t.addEventListener('click', () => {
        const tileId = t.dataset.tileId;
        const ch = t.dataset.char;
        this.onTileClicked(tileId, ch);
      });
    });

    // スロットのクリック（取り消し）
    const slots = this.container.querySelectorAll('.spelling-slot');
    slots.forEach(s => {
      s.addEventListener('click', () => {
        const idx = parseInt(s.dataset.index, 10);
        this.onSlotClicked(idx);
      });
    });

    // 1文字戻す
    const btnBackspace = this.container.querySelector('#btn-backspace');
    if (btnBackspace) {
      btnBackspace.addEventListener('click', () => {
        this.popLastPlacedTile();
      });
    }

    // スロットリセット
    const btnReset = this.container.querySelector('#btn-reset-slots');
    if (btnReset) {
      btnReset.addEventListener('click', () => {
        this.clearPlacedTiles();
      });
    }

    // タイルシャッフル
    const btnShuffle = this.container.querySelector('#btn-shuffle-tiles');
    if (btnShuffle) {
      btnShuffle.addEventListener('click', () => {
        this.state.candidateTiles = shuffleArray([...this.state.candidateTiles]);
        this.renderUI();
      });
    }

    // ヒントボタン
    const btnHint = this.container.querySelector('#btn-hint');
    if (btnHint) {
      btnHint.addEventListener('click', () => {
        this.applyHint();
      });
    }

    // 自力入力のキリルバー
    const cyrKeys = this.container.querySelectorAll('.btn-cyr-key');
    cyrKeys.forEach(k => {
      k.addEventListener('click', () => {
        const ch = k.dataset.char;
        this.onFreeCharTyped(ch);
      });
    });

    const btnFreeBackspace = this.container.querySelector('#btn-free-backspace');
    if (btnFreeBackspace) {
      btnFreeBackspace.addEventListener('click', () => {
        if (this.state.typedLetters.length > 0) {
          this.state.typedLetters.pop();
          this.updateSlotsAndTilesOnly();
        }
      });
    }
  }

  // ==========================================
  // キーボード打鍵処理（IME・ローマ字完全サポート）
  // ==========================================
  static bindKeyboardInput() {
    if (this.keydownHandler) {
      window.removeEventListener('keydown', this.keydownHandler);
    }

    this.keydownHandler = (e) => {
      if (this.state.hasAnswered || this.state.view !== 'playing') return;

      if (e.key === 'Backspace') {
        e.preventDefault();
        if (this.state.mode === 'tile_arrange') {
          this.popLastPlacedTile();
        } else {
          if (this.state.typedLetters.length > 0) {
            this.state.typedLetters.pop();
            this.updateSlotsAndTilesOnly();
          }
        }
        return;
      }

      if (e.key === 'Enter') {
        if (this.state.mode === 'free_type') {
          this.verifyFreeTypeAnswer();
        } else {
          this.checkArrangeAnswer();
        }
        return;
      }

      let keyChar = e.key ? e.key.toLowerCase() : '';
      const HIRAGANA_MAP = {
        'あ': 'a', 'い': 'i', 'う': 'u', 'え': 'e', 'お': 'o',
        'か': 'k', 'き': 'k', 'く': 'k', 'け': 'k', 'こ': 'k',
        'さ': 's', 'し': 's', 'す': 's', 'せ': 's', 'そ': 's',
        'た': 't', 'ち': 'ch', 'つ': 'ts', 'て': 't', 'と': 't',
        'な': 'n', 'に': 'n', 'ぬ': 'n', 'ね': 'n', 'の': 'n',
        'は': 'h', 'ひ': 'h', 'ふ': 'f', 'へ': 'h', 'ほ': 'h',
        'ま': 'm', 'み': 'm', 'む': 'm', 'め': 'm', 'も': 'm',
        'や': 'y', 'ゆ': 'y', 'よ': 'y',
        'ら': 'r', 'り': 'r', 'る': 'r', 'れ': 'r', 'ろ': 'r',
        'わ': 'w', 'を': 'o', 'ん': 'n',
        'が': 'g', 'ぎ': 'g', 'ぐ': 'g', 'げ': 'g', 'ご': 'g',
        'ざ': 'z', 'じ': 'j', 'ず': 'z', 'ぜ': 'z', 'ぞ': 'z',
        'だ': 'd', 'ぢ': 'd', 'づ': 'd', 'で': 'd', 'ど': 'd',
        'ば': 'b', 'び': 'b', 'ぶ': 'b', 'べ': 'b', 'ぼ': 'b',
        'ぱ': 'p', 'ぴ': 'p', 'ぷ': 'p', 'ぺ': 'p', 'ぽ': 'p'
      };
      if (HIRAGANA_MAP[keyChar]) {
        keyChar = HIRAGANA_MAP[keyChar];
      }

      if ((keyChar === 'process' || e.isComposing) && e.code) {
        if (e.code.startsWith('Key')) {
          keyChar = e.code.slice(3).toLowerCase();
        } else if (e.code === 'Minus') {
          keyChar = '-';
        } else if (e.code === 'Equal') {
          keyChar = '=';
        } else if (e.code === 'Quote') {
          keyChar = "'";
        } else if (e.code === 'BracketLeft') {
          keyChar = '[';
        } else if (e.code === 'BracketRight') {
          keyChar = ']';
        } else if (e.code === 'Semicolon') {
          keyChar = ';';
        }
      }

      if (this.state.mode === 'tile_arrange') {
        const matchTile = this.resolveKeyToTile(keyChar, e);
        if (matchTile) {
          e.preventDefault();
          this.onTileClicked(matchTile.id, matchTile.char);
        }
      } else {
        if (isCyrillic(keyChar)) {
          this.onFreeCharTyped(keyChar);
        } else {
          const cyr = this.resolveLatinCharToCyrillic(keyChar, e);
          if (cyr) {
            this.onFreeCharTyped(cyr);
          }
        }
      }
    };

    window.addEventListener('keydown', this.keydownHandler);
  }

  static resolveKeyToTile(keyChar, e = null) {
    if (!keyChar) return null;
    keyChar = keyChar.toLowerCase();

    const expectedIndex = this.state.placedLetters.length;
    const expectedChar = this.state.targetLetters[expectedIndex];

    const LATIN_TO_CYR = {
      'a': ['а'], 'b': ['б', 'в'], 'c': ['ц', 'ч', 'с'], 'd': ['д'],
      'e': ['э', 'е', 'ё'], 'f': ['ф'], 'g': ['г'], 'h': ['х', 'г'],
      'i': ['и', 'й', 'ы'], 'j': ['ж', 'й', 'дз'], 'k': ['к', 'х'],
      'l': ['л'], 'm': ['м'], 'n': ['н'], 'o': ['о', 'ө', 'ё'],
      'p': ['п'], 'q': ['к'], 'r': ['р'], 's': ['с', 'ш', 'щ'],
      't': ['т'], 'u': ['у', 'ү'], 'v': ['в'], 'w': ['в'],
      'x': ['х', 'ч'], 'y': ['й', 'ы', 'я', 'ю'], 'z': ['з', 'ж']
    };

    const QWERTY_CYRILLIC_PHYSICAL = {
      'q': 'й', 'w': 'ц', 'e': 'у', 'r': 'к', 't': 'е', 'y': 'н', 'u': 'г', 'i': 'ш', 'o': 'щ', 'p': 'з',
      '[': 'х', ']': 'ъ', 'a': 'ф', 's': 'ы', 'd': 'в', 'f': 'а', 'g': 'п', 'h': 'р', 'j': 'о', 'k': 'л',
      'l': 'д', ';': 'ж', "'": 'э', 'z': 'я', 'x': 'ч', 'c': 'с', 'v': 'м', 'b': 'и', 'n': 'т', 'm': 'ь'
    };

    const availableTiles = this.state.candidateTiles.filter(t => !t.isUsed);
    if (availableTiles.length === 0) return null;

    if (expectedChar) {
      if (keyChar === expectedChar) {
        const direct = availableTiles.find(t => t.char === expectedChar);
        if (direct) return direct;
      }
      const mappedExpected = LATIN_TO_CYR[keyChar] || [];
      if (mappedExpected.includes(expectedChar)) {
        const phonetic = availableTiles.find(t => t.char === expectedChar);
        if (phonetic) return phonetic;
      }
      const qwertyExpected = QWERTY_CYRILLIC_PHYSICAL[keyChar];
      if (qwertyExpected === expectedChar) {
        const qwMatch = availableTiles.find(t => t.char === expectedChar);
        if (qwMatch) return qwMatch;
      }
    }

    const directAny = availableTiles.find(t => t.char === keyChar);
    if (directAny) return directAny;

    const possibleCyrs = LATIN_TO_CYR[keyChar] || [];
    for (const cyr of possibleCyrs) {
      const match = availableTiles.find(t => t.char === cyr);
      if (match) return match;
    }

    const qwertyChar = QWERTY_CYRILLIC_PHYSICAL[keyChar];
    if (qwertyChar) {
      const qwMatch = availableTiles.find(t => t.char === qwertyChar);
      if (qwMatch) return qwMatch;
    }

    return null;
  }

  static resolveLatinCharToCyrillic(latinKey, e = null) {
    if (!latinKey) return null;
    latinKey = latinKey.toLowerCase();

    const expectedIndex = this.state.typedLetters.length;
    const expectedChar = this.state.targetLetters[expectedIndex];

    const LATIN_TO_CYR = {
      'a': ['а'], 'b': ['б', 'в'], 'c': ['ц', 'ч', 'с'], 'd': ['д'],
      'e': ['э', 'е', 'ё'], 'f': ['ф'], 'g': ['г'], 'h': ['х', 'г'],
      'i': ['и', 'й', 'ы'], 'j': ['ж', 'й'], 'k': ['к', 'х'],
      'l': ['л'], 'm': ['м'], 'n': ['н'], 'o': ['о', 'ө', 'ё'],
      'p': ['п'], 'q': ['к'], 'r': ['р'], 's': ['с', 'ш', 'щ'],
      't': ['т'], 'u': ['у', 'ү'], 'v': ['в'], 'w': ['в'],
      'x': ['х', 'ч'], 'y': ['й', 'ы', 'я', 'ю'], 'z': ['з', 'ж']
    };

    const candidates = LATIN_TO_CYR[latinKey] || [];
    if (expectedChar && candidates.includes(expectedChar)) {
      return expectedChar;
    }
    return candidates[0] || null;
  }

  // ==========================================
  // タイル操作と回答判定（部分更新でチカチカゼロ）
  // ==========================================
  static onTileClicked(tileId, char) {
    if (this.state.hasAnswered) return;
    if (this.state.placedLetters.length >= this.state.targetLetters.length) return;

    const tile = this.state.candidateTiles.find(t => t.id === tileId);
    if (!tile || tile.isUsed) return;

    tile.isUsed = true;
    this.state.placedLetters.push({ tileId, char });
    try {
      SoundEffects.playTile();
    } catch (_) {}

    // チカチカ防止：スロットとタイルのみを部分更新
    this.updateSlotsAndTilesOnly();

    if (this.state.placedLetters.length === this.state.targetLetters.length) {
      this.checkArrangeAnswer();
    }
  }

  static onSlotClicked(index) {
    if (this.state.hasAnswered || this.state.mode !== 'tile_arrange') return;
    if (index < 0 || index >= this.state.placedLetters.length) return;

    const removed = this.state.placedLetters.splice(index, 1)[0];
    if (removed) {
      const tile = this.state.candidateTiles.find(t => t.id === removed.tileId);
      if (tile) tile.isUsed = false;
    }
    this.updateSlotsAndTilesOnly();
  }

  static popLastPlacedTile() {
    if (this.state.placedLetters.length === 0) return;
    const removed = this.state.placedLetters.pop();
    if (removed) {
      const tile = this.state.candidateTiles.find(t => t.id === removed.tileId);
      if (tile) tile.isUsed = false;
    }
    this.updateSlotsAndTilesOnly();
  }

  static clearPlacedTiles() {
    this.state.placedLetters = [];
    this.state.candidateTiles.forEach(t => t.isUsed = false);
    this.updateSlotsAndTilesOnly();
  }

  static applyHint() {
    if (this.state.hasAnswered) return;
    const currentLen = this.state.placedLetters.length;
    if (currentLen >= this.state.targetLetters.length) return;

    const nextChar = this.state.targetLetters[currentLen];
    const availableTile = this.state.candidateTiles.find(t => !t.isUsed && t.char === nextChar);

    if (availableTile) {
      this.state.hintsUsed++;
      this.onTileClicked(availableTile.id, availableTile.char);
    }
  }

  static checkArrangeAnswer() {
    const placedStr = this.state.placedLetters.map(p => p.char).join('');
    const targetStr = this.state.targetLetters.join('');

    if (placedStr === targetStr) {
      this.onCorrectAnswer();
    } else {
      this.onWrongAnswer();
    }
  }

  static onFreeCharTyped(char) {
    if (this.state.hasAnswered) return;
    if (this.state.typedLetters.length >= this.state.targetLetters.length) return;

    this.state.typedLetters.push(char);
    try {
      SoundEffects.playTile();
    } catch (_) {}
    this.updateSlotsAndTilesOnly();

    if (this.state.typedLetters.length === this.state.targetLetters.length) {
      this.verifyFreeTypeAnswer();
    }
  }

  static verifyFreeTypeAnswer() {
    const typedStr = this.state.typedLetters.join('');
    const targetStr = this.state.targetLetters.join('');

    if (typedStr === targetStr) {
      this.onCorrectAnswer();
    } else {
      this.onWrongAnswer();
    }
  }

  // ==========================================
  // 正解・誤答・タイムアウト（演出）
  // ==========================================
  static onCorrectAnswer() {
    this.stopFallTimer();
    this.state.hasAnswered = true;
    this.state.isMistake = false;
    this.state.combo++;
    if (this.state.combo > this.state.maxCombo) {
      this.state.maxCombo = this.state.combo;
    }

    // スコア加算
    const pts = 10 + Math.min(this.state.combo * 2, 20);
    this.state.score += pts;
    this.state.fishFedCount++;
    this.state.todayTotalFed++;
    this.saveTodayFedCount();

    // 満腹度加算 (0〜5)
    this.state.fullness++;
    let isFever = false;
    if (this.state.fullness >= 5) {
      isFever = true;
      this.state.fullness = 0;
      this.state.score += 50;
      try {
        if (typeof GamificationService !== 'undefined' && typeof GamificationService.addXp === 'function') {
          GamificationService.addXp(50);
        }
      } catch (e) {
        console.warn('GamificationService.addXp error:', e);
      }
    } else {
      try {
        if (typeof GamificationService !== 'undefined' && typeof GamificationService.addXp === 'function') {
          GamificationService.addXp(15);
        }
      } catch (e) {
        console.warn('GamificationService.addXp error:', e);
      }
    }

    // レーザー発射＆魚ヒット演出
    this.state.isLaserShooting = true;
    this.state.isFishHit = true;
    this.state.mascotMood = 'happy';
    this.state.mascotMessage = `⚡ ズキューン！命中！お魚を撃ち落としたよ！ (+${pts} pt)`;

    try {
      SoundEffects.playCorrect();
    } catch (_) {}

    this.renderUI();

    // 400ms後: レーザー終了、魚がペンギンへ落下・捕食
    setTimeout(() => {
      this.state.isLaserShooting = false;
      this.state.isFishHit = false;
      this.state.isFishCaught = true;
      this.state.isFeeding = true;
      this.state.mascotMood = isFever ? 'celebrate' : 'happy';
      this.state.mascotMessage = isFever 
        ? '🎉 満腹フィーバー！！ペンギン大満足！ボーナス +50 XP！' 
        : `モグモグ！美味しい！！ амттай байна! 🐟😋 (+${pts} pt)`;

      try {
        SoundEffects.playMunch();
      } catch (_) {}

      try {
        SpeechService.speak(this.state.currentWord.mongolian, { rate: 0.9 });
      } catch (_) {}

      this.renderUI();

      // 1.5秒後に次の問題へ
      setTimeout(() => {
        this.nextWord();
      }, 1500);
    }, 450);

    // 履歴追加
    this.state.answeredLog.push({
      word: this.state.currentWord,
      isCorrect: true,
      userAnswer: this.state.targetLetters.join('')
    });
  }

  static onWrongAnswer() {
    this.state.isMistake = true;
    this.state.combo = 0;
    this.state.mascotMood = 'sad';
    this.state.mascotMessage = 'うーん、惜しい！文字を直してもう一度！🐧';
    try {
      SoundEffects.playWrong();
    } catch (_) {}
    
    const msgEl = this.container?.querySelector('#penguin-mascot-msg');
    if (msgEl) msgEl.textContent = this.state.mascotMessage;
    const svgEl = this.container?.querySelector('#penguin-svg-wrapper');
    if (svgEl) svgEl.innerHTML = PenguinMascot.getSvg('sad', 54);

    setTimeout(() => {
      if (this.state.isMistake && this.state.placedLetters.length > 0) {
        this.popLastPlacedTile();
      }
    }, 450);
  }

  static onFishEscaped() {
    this.state.hasAnswered = true;
    this.state.isFishEscaped = true;
    this.state.combo = 0;
    this.state.mascotMood = 'sad';
    const correctWord = this.state.targetLetters.join('');
    this.state.mascotMessage = `ああっ…逃げちゃった！💦 正解は「${correctWord}」だよ！`;

    try {
      SoundEffects.playWrong();
    } catch (_) {}

    if (this.state.currentWord) {
      const w = this.state.currentWord;
      const userText = this.state.mode === 'tile_arrange'
        ? (this.state.placedLetters || []).map(l => l.char).join('')
        : (this.state.typedLetters || []).join('');
      try {
        StorageService.recordMistake({
          question: `【スペリング】${w.japanese}`,
          userAnswer: userText || '(時間切れ)',
          correctAnswer: w.dictForm || w.mongolian,
          type: 'word',
          category: 'スペリング',
          explanation: `${w.japanese} = ${w.dictForm || w.mongolian}`
        });
      } catch (_) {}
    }

    this.state.answeredLog.push({
      word: this.state.currentWord,
      isCorrect: false,
      userAnswer: '（時間切れ）'
    });

    this.renderUI();

    // 2秒後に次の問題へ
    setTimeout(() => {
      this.nextWord();
    }, 2000);
  }

  static nextWord() {
    this.state.currentIndex++;
    if (this.state.currentIndex < this.state.questions.length) {
      this.loadCurrentWord();
      this.renderUI();
    } else {
      this.showResult();
    }
  }

  // ==========================================
  // 結果発表画面
  // ==========================================
  static showResult() {
    this.stopFallTimer();
    this.state.view = 'result';
    if (this.keydownHandler) {
      window.removeEventListener('keydown', this.keydownHandler);
      this.keydownHandler = null;
    }
    this.renderResultUI();
  }

  static renderResultUI() {
    if (!this.container) return;
    const { score, fishFedCount, maxCombo, answeredLog } = this.state;
    const totalQ = answeredLog.length;
    const correctCount = answeredLog.filter(l => l.isCorrect).length;
    const wrongCount = totalQ - correctCount;
    const accuracy = totalQ > 0 ? Math.round((correctCount / totalQ) * 100) : 0;
    const currentFilter = this.state.resultFilter || 'all';

    const filteredLog = answeredLog.filter(item => {
      if (currentFilter === 'correct') return item.isCorrect;
      if (currentFilter === 'wrong') return !item.isCorrect;
      return true;
    });

    this.container.innerHTML = `
      <div class="max-w-2xl mx-auto px-4 py-8 space-y-6">
        <div class="bg-white rounded-3xl border-2 border-sky-300 p-6 sm:p-8 shadow-xl text-center space-y-5">
          
          <div class="space-y-2">
            <span class="text-5xl">🐟🎉</span>
            <h3 class="text-2xl font-black text-slate-800">スペルシューター 結果発表！</h3>
            <p class="text-xs text-slate-500">お魚を撃ち落としてペンギンにご飯をたくさんあげられました！</p>
          </div>

          <!-- スコア概要 -->
          <div class="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <div class="bg-sky-50 rounded-2xl p-3 border border-sky-200">
              <div class="text-[10px] font-bold text-sky-600">総合スコア</div>
              <div class="text-2xl font-black text-sky-800">${score} pt</div>
            </div>
            <div class="bg-amber-50 rounded-2xl p-3 border border-amber-200">
              <div class="text-[10px] font-bold text-amber-600">あげたお魚</div>
              <div class="text-2xl font-black text-amber-800">${fishFedCount} 匹</div>
            </div>
            <div class="bg-emerald-50 rounded-2xl p-3 border border-emerald-200">
              <div class="text-[10px] font-bold text-emerald-600">正解率</div>
              <div class="text-2xl font-black text-emerald-800">${accuracy}%</div>
            </div>
            <div class="bg-purple-50 rounded-2xl p-3 border border-purple-200">
              <div class="text-[10px] font-bold text-purple-600">最大コンボ</div>
              <div class="text-2xl font-black text-purple-800">${maxCombo}</div>
            </div>
          </div>

          <!-- マスコットコメント -->
          <div class="bg-gradient-to-r from-sky-100 to-cyan-100 rounded-2xl p-4 flex items-center gap-4 text-left border border-sky-200">
            <div class="w-16 h-16 shrink-0 flex items-center justify-center">
              ${PenguinMascot.getSvg(accuracy >= 80 ? 'celebrate' : 'happy', 60)}
            </div>
            <div>
              <div class="text-xs font-black text-sky-900">
                ${accuracy >= 80 ? '🌟 すごい腕前！ペンギンも大喜び！' : '👍 ナイスファイト！いっぱいお魚を食べられたよ！'}
              </div>
              <p class="text-xs text-sky-800 mt-0.5 leading-relaxed">
                落ちてくる前に正しくスペルを入力することで、モンゴル語のキリル文字が指と頭にしっかり定着します！
              </p>
            </div>
          </div>

          ${wrongCount > 0 ? `
            <!-- 間違いノート自動保存通知バナー ＆ 直行ボタン -->
            <div class="p-3.5 bg-rose-50 dark:bg-rose-950/50 border border-rose-200 dark:border-rose-800 rounded-2xl flex flex-col sm:flex-row items-center justify-between gap-3 shadow-2xs text-left">
              <div class="text-xs text-rose-800 dark:text-rose-200 font-bold flex items-center gap-1.5">
                <span class="text-base">🔥</span>
                <span>間違えた <strong>${wrongCount}</strong> 単語を「間違いノート」に自動保存しました</span>
              </div>
              <button type="button" id="btn-goto-mistakes-from-spelling" class="w-full sm:w-auto px-4 py-2 bg-gradient-to-r from-rose-500 to-amber-500 hover:from-rose-600 hover:to-amber-600 text-white font-black rounded-xl text-xs shadow-xs transition-all flex items-center justify-center gap-1.5 cursor-pointer shrink-0">
                <span>間違いノートで特訓</span>
                <span>→</span>
              </button>
            </div>
          ` : ''}

          <!-- 単語レビュー一覧 -->
          <div class="space-y-2 text-left">
            <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 pb-1 border-b border-slate-100">
              <h4 class="text-xs font-black text-slate-700 uppercase tracking-wider flex items-center gap-1.5">
                <span>📋</span> 今回の単語振り返り (${totalQ}語)
              </h4>
              <div class="flex items-center gap-1 bg-slate-100 p-1 rounded-xl text-xs font-bold self-start sm:self-auto">
                <button type="button" class="filter-spelling-btn px-2.5 py-1 rounded-lg transition-all cursor-pointer ${currentFilter === 'all' ? 'bg-white text-slate-900 shadow-2xs font-black' : 'text-slate-500 hover:text-slate-800'}" data-filter="all">
                  すべて (${totalQ})
                </button>
                <button type="button" class="filter-spelling-btn px-2.5 py-1 rounded-lg transition-all cursor-pointer ${currentFilter === 'correct' ? 'bg-emerald-600 text-white shadow-2xs font-black' : 'text-slate-500 hover:text-emerald-700'}" data-filter="correct">
                  ⭕ 正解 (${correctCount})
                </button>
                <button type="button" class="filter-spelling-btn px-2.5 py-1 rounded-lg transition-all cursor-pointer ${currentFilter === 'wrong' ? 'bg-rose-600 text-white shadow-2xs font-black' : 'text-slate-500 hover:text-rose-700'}" data-filter="wrong">
                  ❌ 不正解 (${wrongCount})
                </button>
              </div>
            </div>

            ${filteredLog.length === 0 ? `
              <div class="text-center py-4 text-xs text-slate-400">
                該当する単語はありません。
              </div>
            ` : `
              <div class="divide-y divide-slate-100 border border-slate-200 rounded-xl overflow-hidden max-h-56 overflow-y-auto">
                ${filteredLog.map(item => `
                  <div class="p-3 bg-slate-50 flex items-center justify-between text-xs">
                    <div class="flex items-center gap-2">
                      <span class="${item.isCorrect ? 'text-emerald-600' : 'text-rose-600'} font-black text-base">
                        ${item.isCorrect ? '⭕' : '❌'}
                      </span>
                      <div>
                        <div class="font-bold font-mono text-slate-800 text-sm">${item.word.mongolian}</div>
                        <div class="text-slate-500 text-[11px]">${item.word.japanese}</div>
                        ${!item.isCorrect && item.typedText ? `
                          <div class="text-rose-600 text-[10px]">あなたの入力: <span class="line-through font-mono">${item.typedText}</span></div>
                        ` : ''}
                      </div>
                    </div>
                    <button type="button" class="btn-review-audio p-1.5 text-slate-400 hover:text-sky-600 rounded-lg transition-all" data-text="${item.word.mongolian}">
                      🔊
                    </button>
                  </div>
                `).join('')}
              </div>
            `}
          </div>

          <!-- アクションボタン -->
          <div class="flex items-center gap-3 pt-2">
            <button type="button" id="btn-replay" class="flex-1 py-3.5 bg-gradient-to-r from-sky-500 to-blue-600 hover:from-sky-600 hover:to-blue-700 text-white font-black text-sm rounded-xl shadow-md transition-all active:scale-98">
              もう一度あそぶ 🔄
            </button>
            <button type="button" id="btn-result-home" class="flex-1 py-3.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-black text-sm rounded-xl transition-all">
              単語ゲームへ戻る 🎮
            </button>
          </div>
        </div>
      </div>
    `;

    // フィルターボタンイベント
    this.container.querySelectorAll('.filter-spelling-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        this.state.resultFilter = btn.dataset.filter;
        this.renderResultUI();
      });
    });

    // 間違いノートへ直行
    const gotoMistakesBtn = this.container.querySelector('#btn-goto-mistakes-from-spelling');
    if (gotoMistakesBtn) {
      gotoMistakesBtn.addEventListener('click', () => {
        if (this.onNavigate) {
          if (typeof ReviewNotebookComponent !== 'undefined') {
            ReviewNotebookComponent.state.view = 'list';
            ReviewNotebookComponent.state.filterType = 'all';
          }
          this.onNavigate('review');
        }
      });
    }

    const btnReplay = this.container.querySelector('#btn-replay');
    if (btnReplay) {
      btnReplay.addEventListener('click', () => {
        this.initGame(false);
      });
    }

    const btnHome = this.container.querySelector('#btn-result-home');
    if (btnHome) {
      btnHome.addEventListener('click', () => {
        if (this.onNavigate) this.onNavigate(this.returnTarget || 'word_game');
      });
    }

    const audioBtns = this.container.querySelectorAll('.btn-review-audio');
    audioBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const text = btn.dataset.text;
        if (text) SpeechService.speak(text, { rate: 0.9 });
      });
    });
  }
}


// === js/components/Flashcards.js ===
// フラッシュカードコンポーネント（3D反転アニメーション ＆ SRS 4段階評価）




class FlashcardsComponent {
  static state = {
    category: 'all',
    cards: [],
    currentIndex: 0,
    isFlipped: false,
    stats: {
      again: 0,
      hard: 0,
      good: 0,
      easy: 0
    }
  };

  static render(container, onNavigate) {
    this.container = container;
    this.onNavigate = onNavigate;
    this.initCards();
    this.renderCardView();
  }

  static initCards() {
    let list = StorageService.getVocabulary();
    if (this.state.category !== 'all') {
      list = list.filter(v => v.category === this.state.category);
    }
    this.state.cards = shuffleArray(list);
    this.state.currentIndex = 0;
    this.state.isFlipped = false;
    this.state.stats = { again: 0, hard: 0, good: 0, easy: 0 };
  }

  static renderCardView() {
    const vocabList = StorageService.getVocabulary();
    const categories = Array.from(new Set(vocabList.map(v => v.category || 'その他'))).filter(Boolean);
    const card = this.state.cards[this.state.currentIndex];
    const total = this.state.cards.length;
    const currentNum = this.state.currentIndex + 1;

    if (!card || total === 0) {
      this.container.innerHTML = `
        <div class="animate-fade-in max-w-xl mx-auto px-4 py-8 text-center space-y-4">
          <div class="text-4xl">🃏</div>
          <h2 class="text-lg font-bold text-slate-800">カードが見つかりません</h2>
          <p class="text-xs text-slate-500">カテゴリーを変更するか、単語を登録してください。</p>
          <button type="button" id="btn-back-home" class="px-4 py-2 bg-emerald-600 text-white rounded-lg text-xs font-bold">
            ホームへ戻る
          </button>
        </div>
      `;
      this.container.querySelector('#btn-back-home').addEventListener('click', () => {
        if (this.onNavigate) this.onNavigate('home');
      });
      return;
    }

    this.container.innerHTML = `
      <div class="animate-fade-in max-w-xl mx-auto px-4 py-3 space-y-4">
        
        <!-- コントロールバー -->
        <div class="flex items-center justify-between gap-2 border-b border-slate-200 pb-2.5">
          <div class="flex items-center gap-1.5">
            <span class="text-xl">🃏</span>
            <select id="select-flash-category" class="text-xs p-1.5 bg-slate-100 border border-slate-200 rounded-lg font-bold text-slate-700">
              <option value="all">全単語 (${vocabList.length}語)</option>
              ${categories.map(c => `<option value="${c}" ${this.state.category === c ? 'selected' : ''}>${c}</option>`).join('')}
            </select>
          </div>

          <div class="flex items-center gap-2">
            <span class="text-xs font-bold text-slate-500">${currentNum} / ${total}</span>
            <button type="button" id="btn-shuffle-cards" class="text-xs px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-md font-medium" title="シャッフル">
              🔀
            </button>
            <button type="button" id="btn-flash-home" class="text-xs text-slate-400 hover:text-slate-700">
              ✕
            </button>
          </div>
        </div>

        <!-- 3Dフリップカード本体 -->
        <div class="flip-card w-full h-[320px] sm:h-[340px] cursor-pointer ${this.state.isFlipped ? 'flipped' : ''}" id="flashcard-element">
          <div class="flip-card-inner shadow-lg rounded-2xl">
            
            <!-- カードの表（日本語） -->
            <div class="flip-card-front bg-white border-2 border-slate-200 p-6 flex flex-col justify-between select-none">
              <div class="flex justify-between items-start">
                <span class="text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-800 border border-emerald-200">
                  ${card.pos || '単語'}
                </span>
                <span class="text-xs text-amber-500 font-bold">${card.priority || '★★★'}</span>
              </div>

              <div class="text-center my-auto">
                <div class="mb-3 flex justify-center">
                  ${(typeof getWordIllustrationHTML === 'function') ? getWordIllustrationHTML(card, { size: 'xl' }) : ''}
                </div>
                <div class="text-xs text-slate-400 dark:text-slate-400 mb-1">日本語</div>
                <div class="text-2xl sm:text-3xl font-extrabold text-slate-800 dark:text-white tracking-tight">
                  ${card.japanese}
                </div>
                ${card.category ? `
                  <div class="text-[11px] text-slate-400 dark:text-slate-400 mt-2">${card.category}</div>
                ` : ''}
              </div>

              <div class="text-center text-xs text-slate-400 font-medium">
                👆 タップしてモンゴル語を確認
              </div>
            </div>

            <!-- カードの裏（モンゴル語・発音・語幹・例文） -->
            <div class="flip-card-back bg-gradient-to-b from-emerald-50/90 to-teal-50 border-2 border-emerald-400 p-6 flex flex-col justify-between text-left select-none overflow-y-auto">
              <div class="flex justify-between items-start border-b border-emerald-200/60 pb-2">
                <span class="text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-900">
                  ${card.pos || '単語'}
                </span>
                <button type="button" id="btn-flash-speak" class="text-xs px-2.5 py-1 bg-white hover:bg-emerald-100 text-emerald-800 border border-emerald-300 rounded-full font-semibold shadow-2xs inline-flex items-center gap-1">
                  🔊 発音
                </button>
              </div>

              ${(() => {
                const details = getWordGrammarDetails(card);
                return `
                  <div class="my-auto py-2 space-y-2">
                    <div class="flex items-center gap-3">
                      ${(typeof getWordIllustrationHTML === 'function') ? getWordIllustrationHTML(card, { size: 'lg' }) : ''}
                      <div class="text-2xl sm:text-3xl font-black text-slate-900 dark:text-white cyrillic-text">
                        ${details.dictForm || card.mongolian}
                      </div>
                    </div>

                    ${(typeof isPronunciationCautionWord === 'function' && isPronunciationCautionWord(card) && card.pronunciation) ? `
                      <div class="text-xs text-amber-800 font-bold bg-amber-50 px-2 py-0.5 rounded-full inline-block border border-amber-200">
                        ⚠️ 読み注意: ${card.pronunciation}
                      </div>
                    ` : ''}

                    ${details.isVerb ? `
                      <div class="bg-white/80 p-2.5 rounded-lg border border-emerald-200 text-xs space-y-1">
                        <div class="flex items-center justify-between">
                          <span class="text-slate-500">📖 辞書形: <b class="text-slate-900 cyrillic-text">${details.dictForm}</b></span>
                          <span class="text-emerald-700">🌱 語幹: <b class="text-emerald-900 cyrillic-text">${details.root}</b></span>
                        </div>
                        <div class="text-[11px] text-slate-600 pt-1 border-t border-slate-100">
                          🔍 ${details.derivation}
                        </div>
                      </div>
                    ` : (card.root ? `
                      <div class="text-xs text-slate-700">
                        語幹: <span class="font-bold text-emerald-900 cyrillic-text">${card.root}</span>
                      </div>
                    ` : '')}

                    ${card.note ? `
                      <div class="text-[11px] text-slate-600 bg-white/70 p-2 rounded-lg border border-emerald-200/80">
                        💡 ${card.note}
                      </div>
                    ` : ''}

                    ${(typeof getWordEtymologyHTML === 'function') ? getWordEtymologyHTML(card, card.mongolian) : ''}
                    ${(typeof getWordMnemonicHTML === 'function') ? getWordMnemonicHTML(card, card.mongolian) : ''}
                    ${(typeof getSimilarWordDistinctionHTML === 'function') ? getSimilarWordDistinctionHTML(card, card.mongolian) : ''}

                    ${card.exampleMn ? `
                      <div class="text-xs pt-1.5 border-t border-emerald-200/60">
                        <div class="font-bold cyrillic-text text-slate-800">${card.exampleMn}</div>
                        <div class="text-slate-600 text-[11px]">${card.exampleJa}</div>
                      </div>
                    ` : ''}
                  </div>
                `;
              })()}

              <div class="text-center text-[11px] text-slate-400 pt-1 border-t border-emerald-200/60">
                下のボタンで習熟度を記録
              </div>
            </div>

          </div>
        </div>

        <!-- SRS 評価ボタン（4段階） -->
        <div class="bg-white rounded-2xl p-3 border border-slate-200 shadow-xs space-y-2">
          <div class="text-[11px] text-center font-bold text-slate-400">習熟度を選んで次のカードへ</div>
          <div class="grid grid-cols-4 gap-1.5">
            <button type="button" class="btn-srs py-2.5 px-1 rounded-xl bg-rose-50 hover:bg-rose-100 border border-rose-200 text-rose-800 font-bold text-xs flex flex-col items-center active:scale-95 transition-all" data-rating="again">
              <span class="text-sm">🔄</span>
              <span>もう一度</span>
            </button>

            <button type="button" class="btn-srs py-2.5 px-1 rounded-xl bg-amber-50 hover:bg-amber-100 border border-amber-200 text-amber-800 font-bold text-xs flex flex-col items-center active:scale-95 transition-all" data-rating="hard">
              <span class="text-sm">🤔</span>
              <span>難しい</span>
            </button>

            <button type="button" class="btn-srs py-2.5 px-1 rounded-xl bg-sky-50 hover:bg-sky-100 border border-sky-200 text-sky-800 font-bold text-xs flex flex-col items-center active:scale-95 transition-all" data-rating="good">
              <span class="text-sm">👍</span>
              <span>覚えた</span>
            </button>

            <button type="button" class="btn-srs py-2.5 px-1 rounded-xl bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 text-emerald-800 font-bold text-xs flex flex-col items-center active:scale-95 transition-all" data-rating="easy">
              <span class="text-sm">⚡</span>
              <span>簡単</span>
            </button>
          </div>
        </div>

      </div>
    `;

    this.bindEvents();
  }

  static bindEvents() {
    const cardEl = this.container.querySelector('#flashcard-element');
    if (cardEl) {
      cardEl.addEventListener('click', (e) => {
        // 音声ボタンクリック時はカード反転させない
        if (e.target.closest('#btn-flash-speak')) return;
        this.state.isFlipped = !this.state.isFlipped;
        cardEl.classList.toggle('flipped', this.state.isFlipped);
      });
    }

    const speakBtn = this.container.querySelector('#btn-flash-speak');
    if (speakBtn) {
      speakBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        speakBtn.classList.add('animate-pulse');
        const card = this.state.cards[this.state.currentIndex];
        const res = SpeechService.speakMongolian(card.mongolian);
        if (res && typeof res.then === 'function') {
          res.then(() => speakBtn.classList.remove('animate-pulse'))
             .catch(() => speakBtn.classList.remove('animate-pulse'));
        } else {
          setTimeout(() => speakBtn.classList.remove('animate-pulse'), 1200);
        }
      });
    }

    // カテゴリー選択
    const catSelect = this.container.querySelector('#select-flash-category');
    if (catSelect) {
      catSelect.addEventListener('change', (e) => {
        this.state.category = e.target.value;
        this.initCards();
        this.renderCardView();
      });
    }

    // シャッフル
    const shuffleBtn = this.container.querySelector('#btn-shuffle-cards');
    if (shuffleBtn) {
      shuffleBtn.addEventListener('click', () => {
        this.state.cards = shuffleArray(this.state.cards);
        this.state.currentIndex = 0;
        this.state.isFlipped = false;
        this.renderCardView();
      });
    }

    // ホーム
    const homeBtn = this.container.querySelector('#btn-flash-home');
    if (homeBtn) {
      homeBtn.addEventListener('click', () => {
        if (this.onNavigate) this.onNavigate('home');
      });
    }

    // SRS評価ボタン
    this.container.querySelectorAll('.btn-srs').forEach(btn => {
      btn.addEventListener('click', () => {
        const rating = btn.getAttribute('data-rating');
        this.rateCard(rating);
      });
    });
  }

  static rateCard(rating) {
    const card = this.state.cards[this.state.currentIndex];
    const isCorrect = (rating === 'good' || rating === 'easy');
    StorageService.recordWordAnswer(card.id, isCorrect, rating);

    if (rating === 'again') {
      this.state.stats.again++;
      // 間違いノートへ（問題文に答えを含めない）
      StorageService.recordMistake({
        question: `【カード】${card.japanese}`,
        userAnswer: '(もう一度)',
        correctAnswer: card.mongolian,
        type: 'flashcard',
        category: card.category || '単語',
        explanation: `${card.japanese} = ${card.mongolian}。${card.note || ''}`
      });
    } else if (rating === 'hard') {
      this.state.stats.hard++;
    } else if (rating === 'good') {
      this.state.stats.good++;
    } else if (rating === 'easy') {
      this.state.stats.easy++;
    }

    // 次のカードへ
    if (this.state.currentIndex + 1 < this.state.cards.length) {
      this.state.currentIndex++;
      this.state.isFlipped = false;
      this.renderCardView();
    } else {
      // 終了
      StorageService.recordHistory({
        type: 'flashcard',
        total: this.state.cards.length,
        correct: this.state.stats.good + this.state.stats.easy,
        category: this.state.category
      });
      alert(`フラッシュカードが1周しました！\n覚えた・簡単: ${this.state.stats.good + this.state.stats.easy} 枚\nもう一度・難しい: ${this.state.stats.again + this.state.stats.hard} 枚`);
      this.state.currentIndex = 0;
      this.state.isFlipped = false;
      this.renderCardView();
    }
  }
}


// === js/components/ReviewNotebook.js ===
// 間違いノート・復習コンポーネント





class ReviewNotebookComponent {
  static state = {
    filterType: 'all', // 'all' | 'word' | 'grammar' | 'declension' | 'flashcard'
    showResolved: false,
    testingMode: false,
    testView: 'question', // 'question' | 'result'
    testList: [],
    testIndex: 0,
    currentTestItem: null,
    userAnswer: '',
    hasAnswered: false,
    isCorrect: false,
    testResults: [],
    resultFilter: 'all'
  };

  static render(container, onNavigate) {
    this.container = container;
    this.onNavigate = onNavigate;

    if (this.state.testingMode) {
      if (this.state.testView === 'result') {
        this.renderReviewResult();
      } else {
        this.renderReviewTesting();
      }
    } else {
      this.renderNotebook();
    }
  }

  // --- 0. 統合復習データ取得（間違えた問題・調べた単語・要復習SRS単語） ---
  static getUnifiedReviewItems() {
    // 1. 間違いノートの問題
    const mistakes = StorageService.getMistakes().map(m => ({
      ...m,
      sourceType: 'mistake',
      sourceLabel: '間違い問題'
    }));

    // 2. 読解やタイピングで調べた単語
    const lookedUp = StorageService.getLookedUpWords().map(w => ({
      id: `lookup_${w.id || w.dictForm || w.rawWord}`,
      sourceType: 'looked_up',
      type: 'looked_up',
      category: '調べた単語',
      sourceLabel: '調べた単語',
      question: `【調べた単語】${w.meaning}`,
      correctAnswer: w.dictForm || w.rawWord,
      userAnswer: '',
      explanation: `文中: ${w.rawWord || ''} / 辞書形: ${w.dictForm || ''} / 意味: ${w.meaning} (${w.pos || ''}) ${w.pron ? '発音: ' + w.pron : ''}`,
      wrongCount: w.lookupCount || 1,
      lastWrongDate: w.lookedUpAt || w.lastLookedUpAt || new Date().toISOString(),
      resolved: !!(w.resolved || w.isMastered),
      rawLookup: w
    }));

    // 3. 忘却曲線で振り返るべき単語 (SRS復習期日)
    const dueWords = StorageService.getDueReviewWords().map(w => ({
      id: `due_${w.id}`,
      sourceType: 'due_review',
      type: 'due_review',
      category: '要復習(SRS)',
      sourceLabel: '要復習(SRS)',
      question: `【要復習】${w.japanese}`,
      correctAnswer: w.dictForm || w.mongolian,
      userAnswer: '',
      explanation: `${w.mongolian} = ${w.japanese}（SRSレベル: ${w.srsLevel || 0} / 保持率: ${w.retention || 0}%）`,
      wrongCount: w.wrongCount || 1,
      lastWrongDate: w.nextReviewDate || new Date().toISOString(),
      resolved: false,
      srsWordId: w.id
    }));

    return { mistakes, lookedUp, dueWords, all: [...mistakes, ...lookedUp, ...dueWords] };
  }

  // --- 1. ノート一覧表示 ---
  static renderNotebook() {
    const unified = this.getUnifiedReviewItems();
    let filtered = unified.all;

    if (this.state.filterType === 'mistake') {
      filtered = unified.mistakes;
    } else if (this.state.filterType === 'looked_up') {
      filtered = unified.lookedUp;
    } else if (this.state.filterType === 'due_review') {
      filtered = unified.dueWords;
    } else if (this.state.filterType !== 'all') {
      filtered = unified.mistakes.filter(m => m.type === this.state.filterType);
    }

    if (!this.state.showResolved) {
      filtered = filtered.filter(m => !m.resolved);
    }

    const activeMistakes = unified.mistakes.filter(m => !m.resolved).length;
    const activeLookedUp = unified.lookedUp.filter(m => !m.resolved).length;
    const activeDue = unified.dueWords.filter(m => !m.resolved).length;
    const totalActive = activeMistakes + activeLookedUp + activeDue;
    const totalResolved = unified.all.filter(m => m.resolved).length;

    const countActiveByType = (t) => unified.mistakes.filter(m => !m.resolved && m.type === t).length;
    const activeGrammar = countActiveByType('grammar');
    const activeDeclension = countActiveByType('declension');
    const activeWord = countActiveByType('word');
    const activeReading = countActiveByType('reading');
    const activeListening = countActiveByType('listening');
    const activeWordFamily = countActiveByType('word_family');
    const activeCulture = countActiveByType('culture');
    const activeTyping = countActiveByType('typing');

    const currentFilterActive = filtered.filter(m => !m.resolved).length;

    this.container.innerHTML = `
      <div class="animate-fade-in max-w-2xl mx-auto px-4 py-4 space-y-5">
        
        <!-- ヘッダー -->
        <div class="flex items-center justify-between border-b border-slate-200 pb-3">
          <div class="flex items-center gap-2">
            <span class="text-2xl">🔥</span>
            <div>
              <h2 class="text-lg font-bold text-slate-800">復習ノート（間違い・調べた単語・要復習統合）</h2>
              <p class="text-xs text-slate-500">未克服・復習待ち項目: <span class="font-bold text-rose-600">${totalActive}</span> 件</p>
            </div>
          </div>
          <button type="button" id="btn-back-home" class="text-xs text-slate-500 hover:text-slate-800">
            ✕ ホームへ
          </button>
        </div>

        <!-- 4大カテゴリーサマリーカード（得意同期状況） -->
        <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs">
          <div class="bg-rose-50 border border-rose-200 p-2.5 rounded-xl">
            <div class="text-[10px] text-rose-700 font-bold">🔥 間違い問題</div>
            <div class="text-base font-black text-rose-900 mt-0.5">${activeMistakes} 問</div>
          </div>
          <div class="bg-amber-50 border border-amber-200 p-2.5 rounded-xl">
            <div class="text-[10px] text-amber-700 font-bold">📌 調べた単語</div>
            <div class="text-base font-black text-amber-900 mt-0.5">${activeLookedUp} 語</div>
          </div>
          <div class="bg-sky-50 border border-sky-200 p-2.5 rounded-xl">
            <div class="text-[10px] text-sky-700 font-bold">⏰ 振り返るべき単語</div>
            <div class="text-base font-black text-sky-900 mt-0.5">${activeDue} 語</div>
          </div>
          <div class="bg-emerald-50 border border-emerald-200 p-2.5 rounded-xl">
            <div class="text-[10px] text-emerald-700 font-bold">✓ 克服済み（得意）</div>
            <div class="text-base font-black text-emerald-900 mt-0.5">${totalResolved} 件</div>
          </div>
        </div>

        <!-- 復習開始アクションボタン群 -->
        ${currentFilterActive > 0 ? `
          <div class="bg-gradient-to-r from-rose-500 via-amber-500 to-teal-500 rounded-2xl p-4 text-white shadow-md flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <div class="text-sm font-black flex items-center gap-1.5">
                <span>⚡</span> まとめて復習特訓（正解で得意へ同期！）
              </div>
              <div class="text-xs text-amber-100">
                選択中カテゴリーに <strong class="text-white text-sm">${currentFilterActive}</strong> 件の項目があります。
              </div>
            </div>
            <div class="flex flex-wrap gap-2">
              <button type="button" id="btn-start-all-review" class="px-4 py-2 bg-white text-slate-900 hover:bg-amber-50 text-xs font-black rounded-xl shadow-xs transition-all active:scale-95 cursor-pointer">
                全問特訓スタート (${currentFilterActive}問)
              </button>
            </div>
          </div>
        ` : `
          <div class="bg-emerald-50 rounded-2xl p-5 border border-emerald-200 text-center space-y-1">
            <div class="text-3xl">🎉</div>
            <div class="text-sm font-bold text-emerald-900">このカテゴリーに未克服の項目はありません！</div>
            <div class="text-xs text-emerald-700">素晴らしい習熟度です。新しいテストや読解・タイピングに挑戦しましょう！</div>
          </div>
        `}

        <!-- フィルターバー -->
        <div class="flex flex-wrap items-center justify-between gap-2 bg-white p-3 rounded-xl border border-slate-200 shadow-2xs">
          <div class="flex items-center gap-1 overflow-x-auto scrollbar-none text-xs">
            ${[
              { id: 'all', label: `すべて (${totalActive})` },
              { id: 'mistake', label: `🔥 間違い (${activeMistakes})` },
              { id: 'looked_up', label: `📌 調べた単語 (${activeLookedUp})` },
              { id: 'due_review', label: `⏰ 要復習 (${activeDue})` },
              { id: 'grammar', label: `文法 (${activeGrammar})` },
              { id: 'declension', label: `格変化・活用 (${activeDeclension})` },
              { id: 'word', label: `単語 (${activeWord})` },
              { id: 'reading', label: `読解 (${activeReading})` },
              { id: 'listening', label: 'リスニング' },
              { id: 'word_family', label: `類義語・語根 (${activeWordFamily})` },
              { id: 'culture', label: `文化 (${activeCulture})` },
              { id: 'typing', label: `タイピング (${activeTyping})` }
            ].map(f => `
              <button type="button" class="btn-filter-type px-2.5 py-1.5 rounded-lg font-bold transition-all whitespace-nowrap cursor-pointer ${
                this.state.filterType === f.id ? 'bg-slate-800 text-white' : 'text-slate-600 hover:bg-slate-100'
              }" data-type="${f.id}">
                ${f.label}
              </button>
            `).join('')}
          </div>

          <label class="flex items-center gap-1.5 text-xs text-slate-600 cursor-pointer select-none shrink-0">
            <input type="checkbox" id="check-show-resolved" ${this.state.showResolved ? 'checked' : ''} class="rounded text-emerald-600 focus:ring-0">
            <span>克服済みも表示</span>
          </label>
        </div>

        <!-- 復習ノート一覧カード -->
        <div class="space-y-3">
          ${filtered.length === 0 ? `
            <div class="text-center py-10 text-slate-400 text-xs bg-white rounded-xl border border-slate-200">
              該当する項目はありません。
            </div>
          ` : filtered.map(m => {
            const dateStr = new Date(m.lastWrongDate).toLocaleDateString('ja-JP', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
            const parsed = ReviewNotebookComponent.parseReviewItem(m);
            const sourceBadge = m.sourceType === 'looked_up' 
              ? 'bg-amber-100 text-amber-900 border-amber-300' 
              : (m.sourceType === 'due_review' 
                ? 'bg-sky-100 text-sky-900 border-sky-300' 
                : 'bg-rose-100 text-rose-800 border-rose-300');
            const statusBadge = m.resolved 
              ? 'bg-emerald-100 text-emerald-800' 
              : (m.sourceType === 'looked_up' 
                ? 'bg-amber-100 text-amber-900' 
                : (m.sourceType === 'due_review' 
                  ? 'bg-sky-100 text-sky-900' 
                  : `bg-rose-100 text-rose-800`));
            const statusLabel = m.resolved 
              ? '✓ 克服済み（得意）' 
              : (m.sourceType === 'looked_up' 
                ? '📌 調べた単語' 
                : (m.sourceType === 'due_review' 
                  ? '⏰ 復習期日(SRS)' 
                  : `🔥 誤答 ${m.wrongCount || 1}回`));

            return `
              <div class="bg-white rounded-xl p-4 border ${m.resolved ? 'border-emerald-200 bg-emerald-50/20' : (m.sourceType === 'looked_up' ? 'border-amber-200' : (m.sourceType === 'due_review' ? 'border-sky-200' : 'border-rose-200'))} shadow-2xs space-y-2">
                <div class="flex justify-between items-start gap-2">
                  <div class="flex items-center gap-2">
                    <span class="text-xs font-bold px-2 py-0.5 rounded-full ${statusBadge}">
                      ${statusLabel}
                    </span>
                    <span class="text-[11px] text-slate-400">${m.sourceLabel || m.category || m.type}</span>
                  </div>
                  <div class="flex items-center gap-1.5">
                    <button type="button" class="btn-toggle-resolve text-[11px] px-2 py-0.5 rounded border ${
                      m.resolved ? 'bg-slate-100 text-slate-600 border-slate-300' : 'bg-emerald-50 text-emerald-700 border-emerald-300 font-bold'
                    }" data-id="${m.id}" data-source="${m.sourceType || 'mistake'}" data-srs-id="${m.srsWordId || ''}" data-resolved="${m.resolved}">
                      ${m.resolved ? '未克服に戻す' : '✓ 克服済みにする'}
                    </button>
                    <button type="button" class="btn-delete-mistake text-slate-300 hover:text-rose-500 text-xs px-1 cursor-pointer" data-id="${m.id}" data-source="${m.sourceType || 'mistake'}" title="削除">
                      ✕
                    </button>
                  </div>
                </div>

                <!-- 問題文（イラスト付き・答えの漏洩を防止） -->
                <div class="flex items-center gap-2.5">
                  ${(!parsed.isExplicitNonWord && typeof getWordIllustrationHTML === 'function') ? getWordIllustrationHTML({ mongolian: m.correctAnswer, japanese: m.japanese || parsed.promptText }, { size: 'sm' }) : ''}
                  <div class="text-sm font-bold text-slate-800 dark:text-white cyrillic-text flex items-center gap-1.5 flex-wrap">
                    <span class="text-xs px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 font-bold">${parsed.displayPrefix}</span>
                    <span>${parsed.promptText}</span>
                  </div>
                </div>

                <!-- 回答対比または単語意味 -->
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs pt-1">
                  ${m.userAnswer ? `
                    <div class="p-2 bg-rose-50/80 rounded-lg text-rose-900">
                      <span class="text-slate-400 text-[10px] block">あなたの直前の回答:</span>
                      <span class="font-semibold line-through">${m.userAnswer}</span>
                    </div>
                  ` : `
                    <div class="p-2 bg-slate-50 rounded-lg text-slate-600">
                      <span class="text-slate-400 text-[10px] block">学習タイプ:</span>
                      <span class="font-semibold">${m.sourceLabel || '弱点復習'}</span>
                    </div>
                  `}
                  <div class="p-2 bg-emerald-50/80 rounded-lg text-emerald-950">
                    <span class="text-slate-400 text-[10px] block">${parsed.isExplicitNonWord ? '正解:' : '正しい解答（見出し語）:'}</span>
                    <span class="font-bold cyrillic-text text-emerald-800">${m.correctAnswer}</span>
                  </div>
                </div>

                <!-- 解説 -->
                ${m.explanation ? `
                  <div class="text-[11px] text-slate-600 bg-slate-50 p-2.5 rounded-lg border border-slate-100 leading-relaxed whitespace-pre-line">
                    💡 ${m.explanation}
                  </div>
                ` : ''}

                <div class="text-[10px] text-slate-400 text-right">
                  記録日時: ${dateStr}
                </div>
              </div>
            `;
          }).join('')}
        </div>

      </div>
    `;

    this.bindNotebookEvents();
  }

  static bindNotebookEvents() {
    const homeBtn = this.container.querySelector('#btn-back-home');
    if (homeBtn) {
      homeBtn.addEventListener('click', () => {
        if (this.onNavigate) this.onNavigate('home');
      });
    }

    // フィルターボタン
    this.container.querySelectorAll('.btn-filter-type').forEach(btn => {
      btn.addEventListener('click', () => {
        this.state.filterType = btn.getAttribute('data-type');
        this.renderNotebook();
      });
    });

    // 克服済み表示トグル
    const checkResolved = this.container.querySelector('#check-show-resolved');
    if (checkResolved) {
      checkResolved.addEventListener('change', (e) => {
        this.state.showResolved = e.target.checked;
        this.renderNotebook();
      });
    }

    // 克服トグル
    this.container.querySelectorAll('.btn-toggle-resolve').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        const sourceType = btn.getAttribute('data-source');
        const srsId = btn.getAttribute('data-srs-id');
        const currentResolved = btn.getAttribute('data-resolved') === 'true';
        if (sourceType === 'looked_up') {
          StorageService.markLookedUpWordResolved(id.replace(/^lookup_/, ''), !currentResolved);
        } else if (sourceType === 'due_review') {
          if (srsId) StorageService.recordWordAnswer(srsId, !currentResolved, 'good');
        } else {
          StorageService.markMistakeResolved(id, !currentResolved);
        }
        this.renderNotebook();
      });
    });

    // 削除
    this.container.querySelectorAll('.btn-delete-mistake').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        const sourceType = btn.getAttribute('data-source');
        if (confirm('この記録を削除しますか？')) {
          if (sourceType === 'looked_up') {
            StorageService.deleteLookedUpWord(id.replace(/^lookup_/, ''));
          } else if (sourceType === 'due_review') {
            // SRS復習は完了扱いにして先送り
            const srsId = btn.getAttribute('data-srs-id');
            if (srsId) StorageService.recordWordAnswer(srsId, true, 'easy');
          } else {
            StorageService.removeMistake(id);
          }
          this.renderNotebook();
        }
      });
    });

    // 特訓テスト開始
    const startAllBtn = this.container.querySelector('#btn-start-all-review');
    if (startAllBtn) {
      startAllBtn.addEventListener('click', () => {
        const unified = this.getUnifiedReviewItems();
        let targetList = unified.all;
        if (this.state.filterType === 'mistake') {
          targetList = unified.mistakes;
        } else if (this.state.filterType === 'looked_up') {
          targetList = unified.lookedUp;
        } else if (this.state.filterType === 'due_review') {
          targetList = unified.dueWords;
        } else if (this.state.filterType !== 'all') {
          targetList = unified.mistakes.filter(m => m.type === this.state.filterType);
        }
        const active = targetList.filter(m => !m.resolved);
        if (active.length === 0) return;
        this.state.testList = shuffleArray(active);
        this.state.testIndex = 0;
        this.state.testResults = [];
        this.state.resultFilter = 'all';
        this.state.testingMode = true;
        this.state.testView = 'question';
        this.loadReviewQuestion(0);
      });
    }
  }

  // --- 2. 復習テスト実行画面 ---
  /**
   * 復習問題の出題内容を解析し、問題文から答えの漏洩を除去してクリーンに抽出する
   */
  static parseReviewItem(item) {
    if (!item) return { promptText: '', displayPrefix: '', categoryLabel: '', isCyrillicAnswer: false, placeholder: '正解を入力...', subHint: '', matchedWord: null, details: null, isVerb: false };

    let rawQ = (item.question || '').trim();
    let correctAns = (item.correctAnswer || '').trim();

    // ノイズ文字列「（モンゴル語教科書語彙）」「（JICA訓練所）」「【第X課」を除去
    const cleanRawQ = rawQ.replace(/【第\d+課\s*/g, '【').replace(/[（\(]モンゴル語教科書語彙[）\)]/g, '').replace(/[（\(]JICA訓練所[）\)]/g, '').trim();
    const cleanAns = correctAns.replace(/[（\(]モンゴル語教科書語彙[）\)]/g, '').replace(/[（\(]JICA訓練所[）\)]/g, '').trim();

    const cleanKey = (str) => (str || '').toLowerCase().replace(/[\(\)（）\s.,!?-]/g, '');
    const qClean = cleanKey(cleanRawQ);
    const aClean = cleanKey(cleanAns);

    const allWords = StorageService.getVocabulary();

    // 3段階で確実に該当単語を特定（完全一致 -> 日本語一致 -> 最長モンゴル語部分一致）
    let matchedWord = null;

    // 1. 正解キーの完全一致
    if (aClean) {
      matchedWord = allWords.find(w => {
        const mnClean = cleanKey(w.mongolian);
        const dfClean = cleanKey(w.dictForm);
        const rtClean = cleanKey(w.root);
        return aClean === mnClean || aClean === dfClean || aClean === rtClean;
      });
    }

    // 2. 問題文内の日本語一致（単語マスターの日本語が問題文に含まれているか）
    if (!matchedWord && qClean) {
      matchedWord = allWords.find(w => {
        const jaClean = cleanKey(w.japanese);
        return jaClean && jaClean.length >= 2 && qClean.includes(jaClean);
      });
    }

    // 3. 問題文内のモンゴル語部分一致（長い単語・連語から順に優先マッチ）
    if (!matchedWord && qClean) {
      const sortedWords = [...allWords].sort((a, b) => 
        ((b.dictForm || b.mongolian || '').length) - ((a.dictForm || a.mongolian || '').length)
      );
      matchedWord = sortedWords.find(w => {
        const mnClean = cleanKey(w.mongolian);
        const dfClean = cleanKey(w.dictForm);
        return (mnClean && mnClean.length >= 3 && qClean.includes(mnClean)) ||
               (dfClean && dfClean.length >= 3 && qClean.includes(dfClean));
      });
    }

    const details = matchedWord ? getWordGrammarDetails(matchedWord) : null;
    const isV = details ? details.isVerb : false;
    const isCyrillicAns = /[\u0400-\u04FF]/.test(cleanAns || (matchedWord ? (details.root || details.dictForm) : ''));

    if (item && item.sourceType === 'looked_up') {
      const rawMeaning = item.rawLookup?.meaning || item.meaning || cleanRawQ.replace(/^【調べた単語】\s*/, '');
      return {
        promptText: rawMeaning,
        displayPrefix: '【調べた単語】',
        categoryLabel: '読解・タイピングで調べた単語',
        isCyrillicAnswer: true,
        placeholder: 'キリル文字で入力...',
        subHint: item.rawLookup?.rawWord ? `文中出現形: ${item.rawLookup.rawWord}` : '',
        matchedWord: matchedWord,
        details: details,
        isVerb: isV
      };
    }

    if (item && item.sourceType === 'due_review') {
      const rawJa = cleanRawQ.replace(/^【要復習】\s*/, '');
      return {
        promptText: rawJa,
        displayPrefix: '【要復習(SRS)】',
        categoryLabel: '復習期日到来（忘却曲線）',
        isCyrillicAnswer: true,
        placeholder: 'キリル文字で入力...',
        subHint: '',
        matchedWord: matchedWord,
        details: details,
        isVerb: isV
      };
    }

    let displayPrefix = '';
    let promptText = '';

    const isExplicitNonWord = item && item.type && item.type !== 'word' && item.type !== 'looked_up' && item.type !== 'due_review';

    // 単語マスターとマッチした場合、常にクリーンな見出し情報から出題を構成（ただし明示的に文法・格変化・読解などの非単語問題の場合は問題文を優先）
    if (matchedWord && !isExplicitNonWord) {
      if (isCyrillicAns) {
        displayPrefix = '【単語】';
        promptText = matchedWord.japanese;
      } else {
        displayPrefix = '【日本語訳】';
        promptText = details.dictForm || matchedWord.mongolian;
      }
    } else {
      // 単語マスター以外の問題（文法・格変化・読解・リスニング等）の場合
      if (/⇄|⇆|↔|<->|->/.test(cleanRawQ)) {
        const parts = cleanRawQ.split(/⇄|⇆|↔|<->|->/);
        let sideA = parts[0].trim();
        let sideB = parts[1] ? parts[1].trim() : '';

        const prefixMatch = sideA.match(/^(【[^】]+】)\s*(.*)/);
        if (prefixMatch) {
          displayPrefix = prefixMatch[1];
          sideA = prefixMatch[2].trim();
        } else {
          displayPrefix = '【単語】';
        }

        const hasCyrA = /[\u0400-\u04FF]/.test(sideA);
        const hasCyrB = /[\u0400-\u04FF]/.test(sideB);

        if (hasCyrA && hasCyrB) {
          const w = allWords.find(x => cleanKey(x.mongolian) === cleanKey(sideA) || cleanKey(x.dictForm) === cleanKey(sideA) || cleanKey(x.root) === cleanKey(sideA));
          if (w && !isExplicitNonWord) {
            matchedWord = w;
            promptText = w.japanese;
            displayPrefix = '【単語】';
          } else {
            promptText = sideA;
          }
        } else if (isCyrillicAns) {
          promptText = !hasCyrA ? sideA : (!hasCyrB ? sideB : sideA);
        } else {
          promptText = hasCyrA ? sideA : (hasCyrB ? sideB : sideB);
        }
      } else {
        const prefixMatch = cleanRawQ.match(/^(【[^】]+】)\s*(.*)/);
        if (prefixMatch) {
          displayPrefix = prefixMatch[1];
          promptText = prefixMatch[2].trim();
        } else {
          const typePrefixMap = {
            grammar: '【文法】',
            declension: '【格変化・活用】',
            reading: '【読解】',
            listening: '【リスニング】',
            word_family: '【類義語・語根】',
            culture: '【文化】',
            typing: '【タイピング】',
            word: '【単語】'
          };
          displayPrefix = typePrefixMap[item.type] || '【問題】';
          promptText = cleanRawQ;
        }
      }
    }

    // 万一 promptText 内に ⇄ やノイズが残存していた場合の完全防御サニタイズ
    if (/⇄|⇆|↔|<->|->/.test(promptText)) {
      const parts = promptText.split(/⇄|⇆|↔|<->|->/);
      promptText = parts[0].trim().replace(/^【[^】]+】\s*/, '');
    }
    promptText = promptText.replace(/【第\d+課\s*/g, '【').replace(/[（\(]モンゴル語教科書語彙[）\)]/g, '').replace(/[（\(]JICA訓練所[）\)]/g, '').trim();

    // 答えの漏洩防止サニタイズ（万一 promptText に正解文字列が含まれていた場合は除去）
    if (correctAns && promptText.includes(correctAns)) {
      promptText = promptText.replace(new RegExp(correctAns.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'), '___');
    }

    // байх / байхгүй の誤用自動補正
    if ((cleanAns === 'байх' || cleanAns === 'байхгүй') && (cleanRawQ.includes('ない') || cleanRawQ.includes('いない') || cleanRawQ.includes('バイフグイ'))) {
      correctAns = 'байхгүй';
    }

    // ラベルとサブヒント
    let categoryLabel = "";
    let subHint = "";
    let placeholder = "";

    if (isExplicitNonWord) {
      if (item.type === 'grammar') {
        categoryLabel = "空欄に入る適切な文法・語尾をキリル文字で入力してください";
        subHint = item.category ? `【文法項目: ${item.category}】` : '';
        placeholder = "キリル文字で入力...";
      } else if (item.type === 'declension') {
        categoryLabel = "指定の格変化・活用形をキリル文字で入力してください";
        subHint = item.category ? `【対象: ${item.category}】` : '';
        placeholder = "キリル文字で入力...";
      } else if (item.type === 'reading') {
        categoryLabel = "読解問題の正しい解答を入力してください";
        subHint = item.category ? `【本文: ${item.category}】` : '';
        placeholder = isCyrillicAns ? "キリル文字で入力..." : "日本語で解答を入力...";
      } else if (item.type === 'listening') {
        categoryLabel = "聞き取った正しい語句または内容を入力してください";
        subHint = item.category ? `【リスニング: ${item.category}】` : '';
        placeholder = isCyrillicAns ? "キリル文字で入力..." : "解答を入力...";
      } else if (item.type === 'word_family') {
        categoryLabel = "適切な類義語または接尾辞・派生語を入力してください";
        subHint = item.category ? `【区分: ${item.category}】` : '';
        placeholder = "キリル文字で入力...";
      } else if (item.type === 'culture') {
        categoryLabel = "ことわざ・なぞなぞ・文化知識の正解を入力してください";
        subHint = item.category ? `【文化: ${item.category}】` : '';
        placeholder = isCyrillicAns ? "キリル文字で入力..." : "日本語で入力...";
      } else if (item.type === 'sentence_translation' || item.type === 'typing') {
        categoryLabel = isCyrillicAns ? "日本語に合うモンゴル語文章をキリル文字で入力してください" : "モンゴル語文章の日本語訳を入力してください";
        subHint = item.category ? `【文章入力: ${item.category}】` : '';
        placeholder = isCyrillicAns ? "キリル文字で文章を入力..." : "日本語訳を入力...";
      } else {
        categoryLabel = "問題の正解を入力してください";
        placeholder = isCyrillicAns ? "キリル文字で入力..." : "日本語で入力...";
      }
    } else if (isCyrillicAns) {
      if (isV) {
        categoryLabel = "日本語に合う動詞の【語幹】をキリル文字で入力してください";
        subHint = `【動詞】活用の土台となる【語幹】を入力（例: ${details.dictForm} の語幹「${details.root}」、語尾-ахや括弧は不要）`;
        placeholder = "語幹（または辞書形）をキリル文字で入力...";
      } else {
        categoryLabel = "日本語に合うモンゴル語（キリル文字）を入力してください";
        subHint = (matchedWord && matchedWord.pos) ? `【品詞: ${matchedWord.pos}】` : '';
        placeholder = "キリル文字で入力...";
      }
    } else {
      categoryLabel = "モンゴル語の意味（日本語）を入力してください";
      subHint = (matchedWord && typeof isPronunciationCautionWord === 'function' && isPronunciationCautionWord(matchedWord) && matchedWord.pronunciation) ? `⚠️ 読み注意: ${matchedWord.pronunciation}` : '';
      placeholder = "日本語で意味を入力...";
    }
    return {
      displayPrefix,
      promptText,
      categoryLabel,
      subHint,
      isCyrillicAnswer: isCyrillicAns,
      placeholder,
      matchedWord,
      details,
      isVerb: isV,
      isExplicitNonWord
    };
  }

  static loadReviewQuestion(index) {
    this.state.testIndex = index;
    this.state.currentTestItem = this.state.testList[index];
    this.state.userAnswer = '';
    this.state.hasAnswered = false;
    this.state.isCorrect = false;
    this.renderReviewTesting();
  }

  static renderReviewTesting() {
    const item = this.state.currentTestItem;
    const idx = this.state.testIndex;
    const total = this.state.testList.length;
    const progressPercent = Math.round((idx / total) * 100);
    const parsed = this.parseReviewItem(item);

    this.container.innerHTML = `
      <div class="animate-fade-in max-w-xl mx-auto px-4 py-3 space-y-4">
        
        <div class="space-y-1.5">
          <div class="flex justify-between items-center text-xs font-bold text-slate-500">
            <span>🔥 弱点克服テスト ${idx + 1} / ${total}</span>
            <button type="button" id="btn-quit-review-test" class="text-slate-400 hover:text-slate-700">終了</button>
          </div>
          <div class="w-full bg-slate-200 h-2 rounded-full overflow-hidden">
            <div class="bg-rose-500 h-full transition-all duration-300" style="width: ${progressPercent}%"></div>
          </div>
        </div>

        <!-- 問題カード（答えの漏洩を完全に排除） -->
        <div class="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm text-center">
          <div class="text-xs font-bold text-rose-600 mb-2">${parsed.categoryLabel}</div>
          <div class="text-xl sm:text-2xl font-black text-slate-800 cyrillic-text leading-relaxed">
            <span class="text-sm font-bold text-slate-400 mr-1">${parsed.displayPrefix}</span>
            <span>${parsed.promptText}</span>
          </div>
          ${parsed.subHint ? `
            <div class="mt-2 text-center">
              <button type="button" id="btn-toggle-review-hint" class="text-xs text-slate-400 hover:text-slate-600 bg-slate-50 hover:bg-slate-100 px-3 py-1 rounded-full font-bold border border-slate-200 transition-all inline-flex items-center gap-1.5 cursor-pointer select-none active:scale-95 shadow-2xs">
                <span>💡</span>
                <span id="review-hint-toggle-text">ヒントを見る ▼</span>
              </button>
              <div id="review-hint-content" class="hidden mt-2 animate-fade-in text-xs text-rose-700 bg-rose-50 inline-block px-3 py-1.5 rounded-xl font-medium border border-rose-200">
                ${parsed.subHint}
              </div>
            </div>
          ` : ''}
        </div>

        <!-- 回答エリア -->
        ${!this.state.hasAnswered ? `
          <div class="bg-white rounded-2xl p-4 border border-slate-200 shadow-xs space-y-3">
            <input type="text" id="input-review-answer" 
              class="w-full text-base sm:text-lg p-3 rounded-xl border-2 border-slate-300 focus:border-rose-500 focus:outline-hidden text-center font-bold text-slate-800 cyrillic-text cyrillic-input" 
              placeholder="${parsed.placeholder}" 
              data-cyrillic="${parsed.isCyrillicAnswer ? 'true' : 'false'}"
              autofocus autocomplete="off">

            <!-- キリル文字クイックバー（キリル文字回答時のみ表示） -->
            ${parsed.isCyrillicAnswer ? `
              <div class="flex items-center gap-1 overflow-x-auto py-2 scrollbar-none mt-1">
                <span class="text-[11px] text-slate-400 shrink-0">タップで入力:</span>
                ${SPECIAL_CYRILLIC_BAR.map(c => `
                  <button type="button" class="btn-quick-char px-2 py-1 text-xs font-bold bg-slate-100 hover:bg-rose-100 text-slate-700 rounded border border-slate-200 shrink-0" data-char="${c}">
                    ${c}
                  </button>
                `).join('')}
              </div>
            ` : ''}

            <button type="button" id="btn-submit-review" class="w-full py-3 bg-rose-600 hover:bg-rose-700 text-white font-bold rounded-xl shadow-md transition-all active:scale-98 text-sm">
              回答する（Enter）
            </button>
          </div>
        ` : `
          <div class="animate-fade-in space-y-4">
            <div class="p-5 rounded-2xl border ${this.state.isCorrect ? 'bg-emerald-50 dark:bg-emerald-950/40 border-emerald-300 dark:border-emerald-800 text-emerald-950 dark:text-emerald-100' : 'bg-rose-50 dark:bg-rose-950/50 border-rose-300 dark:border-rose-900/60 text-rose-950 dark:text-rose-100'} shadow-sm">
              <div class="text-2xl font-black mb-3">
                ${this.state.isCorrect ? '🎉 見事克服！正解です！' : '❌ まだ克服できていません'}
              </div>

              ${(() => {
                const isExplicitNonWord = item && item.type && item.type !== 'word' && item.type !== 'looked_up' && item.type !== 'due_review';
                const matchedWord = (!isExplicitNonWord) ? parsed.matchedWord : null;

                // 単語情報がある場合：動詞・名詞・複合語問わず詳細解説＆成り立ちHTMLを完全展開
                if (matchedWord) {
                  return renderGrammarExplanationHTML({
                    correctAnswer: item.correctAnswer,
                    userAnswer: this.state.userAnswer,
                    isCorrect: this.state.isCorrect,
                    item: matchedWord,
                    grammarExplanation: item.explanation,
                    isVerbQuestion: parsed.isVerb
                  });
                }

                // マッチ単語がない場合のフォールバック（イラスト・成り立ち解析・語呂合わせ・ダークモード高コントラスト対応）
                const etymologyHTML = (typeof getWordEtymologyHTML === 'function')
                  ? getWordEtymologyHTML({ mongolian: item.correctAnswer, japanese: item.japanese }, item.correctAnswer)
                  : '';
                const mnemonicHTML = (typeof getWordMnemonicHTML === 'function')
                  ? getWordMnemonicHTML({ mongolian: item.correctAnswer, japanese: item.japanese }, item.correctAnswer)
                  : '';
                const illustrationHTML = (typeof getWordIllustrationHTML === 'function')
                  ? getWordIllustrationHTML({ mongolian: item.correctAnswer, japanese: item.japanese }, { size: 'md' })
                  : '';

                return `
                  <div class="space-y-3 text-xs sm:text-sm">
                    <div class="flex items-center gap-3">
                      ${illustrationHTML}
                      <div>
                        <div class="flex items-center gap-1.5 flex-wrap">
                          <span class="text-slate-500 dark:text-slate-400 font-bold">正解: </span>
                          <span class="font-black text-lg cyrillic-text text-emerald-700 dark:text-emerald-400 correct-answer-text">${item.correctAnswer}${((typeof getWordSynonymNote === 'function' && getWordSynonymNote(item.correctAnswer)) ? ` <span class="text-xs text-slate-500 dark:text-slate-400 font-normal">(${getWordSynonymNote(item.correctAnswer)})</span>` : '')}</span>
                        </div>
                        ${item.japanese ? `<div class="text-xs text-slate-600 dark:text-slate-300 font-semibold mt-0.5">${item.japanese}</div>` : ''}
                      </div>
                    </div>

                    ${!this.state.isCorrect && this.state.userAnswer ? `
                      <div class="p-2.5 rounded-xl bg-rose-100/80 dark:bg-rose-900/40 border border-rose-200 dark:border-rose-800 text-rose-900 dark:text-rose-200">
                        <span>あなたの回答: </span>
                        <span class="font-bold line-through cyrillic-text">${this.state.userAnswer}</span>
                      </div>
                    ` : ''}

                    ${etymologyHTML}
                    ${mnemonicHTML}

                    ${(() => {
                      const syn = (typeof getWordSynonymNote === 'function') ? getWordSynonymNote(item.correctAnswer) : '';
                      const exp = item.explanation || (item.japanese ? `${item.japanese} (辞書形: ${item.correctAnswer})` : '');
                      if (!exp) return '';
                      const displayExp = (syn && !exp.includes(syn)) ? `${exp} (別表現: ${syn})` : exp;
                      return `
                        <div class="p-3 bg-white/95 dark:bg-slate-950/90 rounded-xl border border-slate-200 dark:border-slate-800 text-slate-800 dark:text-slate-200 text-xs leading-relaxed shadow-2xs">
                          💡 ${displayExp}
                        </div>
                      `;
                    })()}
                  </div>
                `;
              })()}
            </div>

            <button type="button" id="btn-next-review-item" class="w-full py-3 bg-rose-600 hover:bg-rose-700 text-white font-bold rounded-xl shadow-md transition-all active:scale-98 text-sm">
              ${idx + 1 < total ? '次の復習問題へ →' : '復習テスト完了！'}
            </button>
          </div>
        `}

      </div>
    `;

    this.bindReviewTestingEvents();
  }

  static bindReviewTestingEvents() {
    const quitBtn = this.container.querySelector('#btn-quit-review-test');
    if (quitBtn) {
      quitBtn.addEventListener('click', () => {
        this.state.testingMode = false;
        this.renderNotebook();
      });
    }

    // ヒントトグル
    const toggleHintBtn = this.container.querySelector('#btn-toggle-review-hint');
    const hintContent = this.container.querySelector('#review-hint-content');
    const hintToggleText = this.container.querySelector('#review-hint-toggle-text');
    if (toggleHintBtn && hintContent) {
      toggleHintBtn.addEventListener('click', (e) => {
        e.preventDefault();
        const isHidden = hintContent.classList.toggle('hidden');
        if (hintToggleText) {
          hintToggleText.textContent = isHidden ? 'ヒントを見る ▼' : 'ヒントを閉じる ▲';
        }
      });
    }

    if (!this.state.hasAnswered) {
      const input = this.container.querySelector('#input-review-answer');
      const submitBtn = this.container.querySelector('#btn-submit-review');

      if (input) {
        input.focus();
        CyrillicKeyboard.setActiveInput(input);
        input.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            this.checkReviewAnswer(input.value);
          }
        });
      }

      if (submitBtn) {
        submitBtn.addEventListener('click', () => {
          if (input) this.checkReviewAnswer(input.value);
        });
      }

      // クイック文字タップ
      this.container.querySelectorAll('.btn-quick-char').forEach(btn => {
        btn.addEventListener('click', () => {
          const char = btn.getAttribute('data-char');
          CyrillicKeyboard.insertChar(char);
        });
      });
    } else {
      const nextBtn = this.container.querySelector('#btn-next-review-item');
      if (nextBtn) {
        nextBtn.focus();
        nextBtn.addEventListener('click', () => {
          if (this.state.testIndex + 1 < this.state.testList.length) {
            this.loadReviewQuestion(this.state.testIndex + 1);
          } else {
            this.state.testView = 'result';
            this.renderReviewResult();
          }
        });
      }
    }
  }

  static checkReviewAnswer(val) {
    const item = this.state.currentTestItem;
    const parsed = this.parseReviewItem(item);
    const isExplicitNonWord = item && item.type && item.type !== 'word' && item.type !== 'looked_up' && item.type !== 'due_review';
    const matchedWord = (!isExplicitNonWord) ? parsed.matchedWord : null;

    let isCorrect = false;

    if (isExplicitNonWord) {
      // 文法・格変化・読解・リスニング・文化等の判定
      if (item.acceptableAnswers && Array.isArray(item.acceptableAnswers)) {
        isCorrect = item.acceptableAnswers.some(ans => isFuzzyMatch(val, ans));
      }
      if (!isCorrect) {
        isCorrect = isFuzzyMatch(val, item.correctAnswer);
      }
      // 選択肢番号 (例: 1, 2) または選択肢テキスト部分一致対応
      if (!isCorrect && item.correctAnswer) {
        const numMatch = item.correctAnswer.match(/^\s*(\d+)[\.\)]\s*(.*)/);
        if (numMatch) {
          if (val.trim() === numMatch[1] || isFuzzyMatch(val, numMatch[2])) {
            isCorrect = true;
          }
        }
      }
    } else if (matchedWord) {
      // 単語判定（語幹、辞書形、マルチワード動詞、隠れ-н、揺らぎ吸収）
      isCorrect = isWordAnswerMatch(val, matchedWord, parsed.isVerb ? 'root_input' : (parsed.isCyrillicAnswer ? 'ja_to_mn' : 'mn_to_ja'));
      if (!isCorrect && parsed.isVerb) {
        // 復習時の特別配慮: 動詞で辞書形 (例: орчуулах) を入力した場合も正解とする
        const uClean = val.trim().toLowerCase().replace(/[.,!?。、！？\s]/g, '');
        const dClean = (parsed.details.dictForm || '').toLowerCase().replace(/[.,!?。、！？\s]/g, '');
        if (uClean === dClean) isCorrect = true;
      }
      if (!isCorrect) {
        isCorrect = isFuzzyMatch(val, item.correctAnswer);
      }
      if (!isCorrect && item.correctAnswer) {
        const syns = (typeof getWordSynonyms === 'function') ? getWordSynonyms(item.correctAnswer) : [];
        const uClean = val.trim().toLowerCase().replace(/[.,!?。、！？\s«»"']/g, '');
        for (const s of syns) {
          if (uClean === s.toLowerCase().replace(/[.,!?。、！？\s«»"']/g, '')) {
            isCorrect = true;
            break;
          }
        }
      }
    } else {
      isCorrect = isFuzzyMatch(val, item.correctAnswer);
      if (!isCorrect && item.correctAnswer) {
        const syns = (typeof getWordSynonyms === 'function') ? getWordSynonyms(item.correctAnswer) : [];
        const uClean = val.trim().toLowerCase().replace(/[.,!?。、！？\s«»"']/g, '');
        for (const s of syns) {
          if (uClean === s.toLowerCase().replace(/[.,!?。、！？\s«»"']/g, '')) {
            isCorrect = true;
            break;
          }
        }
      }
    }

    this.state.hasAnswered = true;
    this.state.userAnswer = val;
    this.state.isCorrect = isCorrect;

    this.state.testResults.push({
      item,
      isCorrect,
      userAnswer: val,
      correctAnswer: item.correctAnswer,
      parsed
    });

    if (isCorrect) {
      SoundEffects.playCorrect();
      // 正解したら克服済みにマーク（履歴は保持され、未克服リストから外れる）
      if (item.sourceType === 'looked_up') {
        const lookupKey = item.rawLookup?.id || item.rawLookup?.dictForm || item.correctAnswer;
        StorageService.markLookedUpWordResolved(lookupKey, true);
      } else if (item.sourceType === 'due_review') {
        if (item.srsWordId) StorageService.recordWordAnswer(item.srsWordId, true, 'good');
      } else {
        StorageService.markMistakeResolved(item.id, true);
      }

      // 対応する単語のSRS進捗も向上（マスター・得意化）
      if (matchedWord) {
        StorageService.recordWordAnswer(matchedWord.id, true);
      }
    } else {
      SoundEffects.playWrong();
      StorageService.recordMistake({
        ...item,
        userAnswer: val
      });
    }

    this.renderReviewTesting();
  }

  // --- 3. 復習テスト結果画面 ---
  static renderReviewResult() {
    const total = this.state.testResults.length;
    const correct = this.state.testResults.filter(r => r.isCorrect).length;
    const wrong = total - correct;
    const percent = total > 0 ? Math.round((correct / total) * 100) : 0;
    const currentFilter = this.state.resultFilter || 'all';

    const filteredResults = this.state.testResults.filter(r => {
      if (currentFilter === 'correct') return r.isCorrect;
      if (currentFilter === 'wrong') return !r.isCorrect;
      return true;
    });

    this.container.innerHTML = `
      <div class="animate-fade-in max-w-xl mx-auto px-4 py-4 space-y-4">
        
        <div class="bg-gradient-to-r from-emerald-600 to-teal-700 rounded-2xl p-6 text-white text-center shadow-lg space-y-2">
          <div class="text-3xl">🎉</div>
          <h2 class="text-lg font-black tracking-wide">弱点克服テスト 完了！</h2>
          <div class="text-xs text-white/90">
            克服・正解: <span class="font-black text-amber-300 text-base">${correct} / ${total} 問</span> (${percent}%)
          </div>
        </div>

        <div class="bg-white rounded-2xl p-5 border border-slate-200 shadow-md text-center space-y-3">
          <div class="flex gap-2">
            <button type="button" id="btn-retry-review-test" class="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs sm:text-sm transition-all active:scale-98 shadow-xs cursor-pointer">
              もう一度復習する
            </button>
            <button type="button" id="btn-back-to-notebook" class="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs sm:text-sm transition-all cursor-pointer">
              間違いノートへ戻る
            </button>
          </div>
        </div>

        <!-- 出題問題の一覧・復習（正解・不正解フィルター切り替え） -->
        <div class="bg-white rounded-2xl p-4 border border-slate-200 shadow-xs space-y-3">
          <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 pb-2 border-b border-slate-100">
            <h3 class="text-sm font-extrabold text-slate-800 flex items-center gap-1.5">
              <span>📋</span> 解答した問題の一覧 (${total}問)
            </h3>
            <div class="flex items-center gap-1 bg-slate-100 p-1 rounded-xl text-xs font-bold self-start sm:self-auto">
              <button type="button" class="filter-review-result-btn px-2.5 py-1 rounded-lg transition-all cursor-pointer ${currentFilter === 'all' ? 'bg-white text-slate-900 shadow-2xs font-black' : 'text-slate-500 hover:text-slate-800'}" data-filter="all">
                すべて (${total})
              </button>
              <button type="button" class="filter-review-result-btn px-2.5 py-1 rounded-lg transition-all cursor-pointer ${currentFilter === 'correct' ? 'bg-emerald-600 text-white shadow-2xs font-black' : 'text-slate-500 hover:text-emerald-700'}" data-filter="correct">
                ⭕ 克服 (${correct})
              </button>
              <button type="button" class="filter-review-result-btn px-2.5 py-1 rounded-lg transition-all cursor-pointer ${currentFilter === 'wrong' ? 'bg-rose-600 text-white shadow-2xs font-black' : 'text-slate-500 hover:text-rose-700'}" data-filter="wrong">
                ❌ 要復習 (${wrong})
              </button>
            </div>
          </div>

          ${filteredResults.length === 0 ? `
            <div class="text-center py-6 text-xs text-slate-400">
              該当する問題はありません。
            </div>
          ` : `
            <div class="divide-y divide-slate-100 max-h-96 overflow-y-auto pr-1">
              ${filteredResults.map(r => {
                const cyrText = /[\u0400-\u04FF]/.test(r.correctAnswer) ? r.correctAnswer : (r.parsed && r.parsed.matchedWord ? r.parsed.matchedWord.mongolian : '');
                return `
                  <div class="py-3 flex items-start justify-between gap-3 text-xs">
                    <div class="space-y-1 flex-1">
                      <div class="flex items-center gap-2">
                        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${r.isCorrect ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'}">
                          ${r.isCorrect ? '⭕ 克服済' : '❌ 要復習'}
                        </span>
                        <span class="font-bold text-slate-900 text-xs sm:text-sm">${r.parsed ? r.parsed.promptText : (r.item.question || '')}</span>
                      </div>
                      <div class="text-slate-700 font-medium">
                        正解: <span class="font-bold text-emerald-800 cyrillic-text correct-answer-text">${r.correctAnswer}</span>
                      </div>
                      ${!r.isCorrect ? `
                        <div class="text-slate-500">
                          あなたの回答: <span class="line-through text-rose-600 font-medium">${r.userAnswer || '(無回答)'}</span>
                        </div>
                      ` : `
                        ${r.userAnswer ? `<div class="text-slate-500">あなたの回答: <span class="text-emerald-700 font-bold">${r.userAnswer}</span> ✅</div>` : ''}
                      `}
                    </div>
                    ${cyrText ? `
                      <button type="button" class="btn-speak-review-result text-slate-400 hover:text-emerald-700 p-2 rounded-xl hover:bg-slate-100 transition-colors cursor-pointer" data-word="${cyrText}" title="発音を聞く">
                        🔊
                      </button>
                    ` : ''}
                  </div>
                `;
              }).join('')}
            </div>
          `}
        </div>
      </div>
    `;

    // フィルターボタンイベント
    this.container.querySelectorAll('.filter-review-result-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        this.state.resultFilter = btn.getAttribute('data-filter');
        this.renderReviewResult();
      });
    });

    // 音声再生
    this.container.querySelectorAll('.btn-speak-review-result').forEach(btn => {
      btn.addEventListener('click', () => {
        const word = btn.getAttribute('data-word');
        if (word) SpeechService.speakMongolian(word);
      });
    });

    this.container.querySelector('#btn-retry-review-test').addEventListener('click', () => {
      const active = StorageService.getMistakes().filter(m => !m.resolved);
      if (active.length > 0) {
        this.state.testList = shuffleArray(active);
        this.state.testIndex = 0;
        this.state.testResults = [];
        this.state.resultFilter = 'all';
        this.state.testingMode = true;
        this.state.testView = 'question';
        this.loadReviewQuestion(0);
      } else {
        alert('未克服の問題はありません！全問マスター達成です！');
        this.state.testingMode = false;
        this.renderNotebook();
      }
    });

    this.container.querySelector('#btn-back-to-notebook').addEventListener('click', () => {
      this.state.testingMode = false;
      this.state.testView = 'question';
      this.renderNotebook();
    });
  }
}


// === js/components/MaterialManager.js ===
// 教材管理・テキスト自動解析・CSV/JSONインポートエクスポートコンポーネント





class MaterialManagerComponent {
  static state = {
    subTab: 'paste', // 'paste' | 'manual' | 'list' | 'backup'
    parsedPreviewItems: [],
    searchQuery: '',
    selectedCategory: 'all',
    editingItem: null
  };

  static render(container, onNavigate) {
    this.container = container;
    this.onNavigate = onNavigate;
    this.renderView();
  }

  static renderView() {
    this.container.innerHTML = `
      <div class="animate-fade-in max-w-3xl mx-auto px-4 py-4 space-y-5">
        
        <!-- ヘッダー -->
        <div class="flex items-center justify-between border-b border-slate-200 pb-3">
          <div class="flex items-center gap-2">
            <span class="text-2xl">📚</span>
            <div>
              <h2 class="text-lg font-bold text-slate-800">教材の登録・管理</h2>
              <p class="text-xs text-slate-500">テキスト貼り付け自動解析、手動追加、CSV/JSONバックアップ</p>
            </div>
          </div>
          <button type="button" id="btn-back-home" class="text-xs text-slate-500 hover:text-slate-800">
            ✕ ホームへ
          </button>
        </div>

        <!-- サブタブ -->
        <div class="flex border-b border-slate-200 text-xs font-bold gap-1 overflow-x-auto scrollbar-none">
          <button type="button" class="subtab-btn px-4 py-2 rounded-t-lg transition-all ${
            this.state.subTab === 'paste' ? 'bg-white text-emerald-800 border-t-2 border-emerald-600 shadow-2xs' : 'text-slate-500 hover:text-slate-800 hover:bg-slate-100'
          }" data-tab="paste">
            📋 テキスト自動解析
          </button>

          <button type="button" class="subtab-btn px-4 py-2 rounded-t-lg transition-all ${
            this.state.subTab === 'manual' ? 'bg-white text-emerald-800 border-t-2 border-emerald-600 shadow-2xs' : 'text-slate-500 hover:text-slate-800 hover:bg-slate-100'
          }" data-tab="manual">
            ✍️ 手動入力
          </button>

          <button type="button" class="subtab-btn px-4 py-2 rounded-t-lg transition-all ${
            this.state.subTab === 'list' ? 'bg-white text-emerald-800 border-t-2 border-emerald-600 shadow-2xs' : 'text-slate-500 hover:text-slate-800 hover:bg-slate-100'
          }" data-tab="list">
            📖 登録教材一覧 (${StorageService.getVocabulary().length}件)
          </button>

          <button type="button" class="subtab-btn px-4 py-2 rounded-t-lg transition-all ${
            this.state.subTab === 'backup' ? 'bg-white text-emerald-800 border-t-2 border-emerald-600 shadow-2xs' : 'text-slate-500 hover:text-slate-800 hover:bg-slate-100'
          }" data-tab="backup">
            💾 バックアップ・復元
          </button>
        </div>

        <!-- タブコンテンツエリア -->
        <div id="material-tab-content">
          ${this.getTabContentHTML()}
        </div>

      </div>
    `;

    this.bindEvents();
  }

  static getTabContentHTML() {
    if (this.state.subTab === 'paste') return this.getPasteHTML();
    if (this.state.subTab === 'manual') return this.getManualHTML();
    if (this.state.subTab === 'list') return this.getListHTML();
    if (this.state.subTab === 'backup') return this.getBackupHTML();
    return '';
  }

  // --- 1. テキスト自動解析タブ ---
  static getPasteHTML() {
    return `
      <div class="bg-white rounded-2xl p-5 border border-slate-200 shadow-xs space-y-4">
        <div>
          <h3 class="text-sm font-bold text-slate-800 mb-1">表形式やテキストを直接貼り付け</h3>
          <p class="text-xs text-slate-500 leading-relaxed">
            Excelからコピーした表（タブ区切り）、CSV、コロン形式（「日本語: 食べる / モンゴル語: идэх / 語幹: ид」）などを自動判別して教材データに変換します。解析結果を画面で修正してから登録できます。
          </p>
        </div>

        <div>
          <textarea id="textarea-paste-input" rows="6" 
            class="w-full text-xs font-mono p-3 rounded-xl border border-slate-300 focus:border-emerald-500 focus:outline-hidden text-slate-800" 
            placeholder="例1:&#10;日本語：食べる&#10;モンゴル語：идэх&#10;語幹：ид&#10;&#10;例2（タブやハイフン区切り）:&#10;学校	сургууль&#10;本	ном"></textarea>
        </div>

        <div class="flex gap-2">
          <button type="button" id="btn-parse-text" class="px-4 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs shadow-xs transition-all active:scale-95 flex items-center gap-1.5">
            <span>⚡</span> 自動解析を実行
          </button>
          <button type="button" id="btn-load-sample-text" class="px-3 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-semibold rounded-xl text-xs transition-all">
            サンプル貼り付け
          </button>
        </div>

        <!-- プレビューと修正テーブル -->
        <div id="parse-preview-container" class="${this.state.parsedPreviewItems.length > 0 ? 'block' : 'hidden'} space-y-3 pt-3 border-t border-slate-100">
          <div class="flex items-center justify-between">
            <h4 class="text-xs font-bold text-slate-700">解析プレビュー（${this.state.parsedPreviewItems.length}件）</h4>
            <button type="button" id="btn-commit-batch" class="px-4 py-2 bg-emerald-700 hover:bg-emerald-800 text-white font-bold rounded-lg text-xs shadow-md transition-all active:scale-95">
              ✓ この内容でアプリに一括登録する
            </button>
          </div>

          <div class="overflow-x-auto max-h-72 border border-slate-200 rounded-xl">
            <table class="w-full text-xs text-left">
              <thead class="bg-slate-50 text-slate-600 uppercase border-b border-slate-200 sticky top-0">
                <tr>
                  <th class="p-2">日本語</th>
                  <th class="p-2">モンゴル語</th>
                  <th class="p-2">語幹</th>
                  <th class="p-2">品詞</th>
                  <th class="p-2">メモ</th>
                  <th class="p-2 w-10">操作</th>
                </tr>
              </thead>
              <tbody class="divide-y divide-slate-100">
                ${this.state.parsedPreviewItems.map((item, idx) => `
                  <tr class="hover:bg-slate-50">
                    <td class="p-1.5"><input type="text" class="preview-edit-field w-full p-1 border rounded text-xs" data-idx="${idx}" data-field="japanese" value="${item.japanese}"></td>
                    <td class="p-1.5"><input type="text" class="preview-edit-field w-full p-1 border rounded text-xs font-bold cyrillic-text" data-idx="${idx}" data-field="mongolian" value="${item.mongolian}"></td>
                    <td class="p-1.5"><input type="text" class="preview-edit-field w-20 p-1 border rounded text-xs cyrillic-text" data-idx="${idx}" data-field="root" value="${item.root || ''}"></td>
                    <td class="p-1.5"><input type="text" class="preview-edit-field w-16 p-1 border rounded text-xs" data-idx="${idx}" data-field="pos" value="${item.pos || ''}"></td>
                    <td class="p-1.5"><input type="text" class="preview-edit-field w-full p-1 border rounded text-xs" data-idx="${idx}" data-field="note" value="${item.note || ''}"></td>
                    <td class="p-1.5 text-center">
                      <button type="button" class="btn-remove-preview-row text-rose-500 hover:text-rose-700 font-bold" data-idx="${idx}">✕</button>
                    </td>
                  </tr>
                `).join('')}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    `;
  }

  // --- 2. 手動入力タブ ---
  static getManualHTML() {
    return `
      <div class="bg-white rounded-2xl p-5 border border-slate-200 shadow-xs space-y-4">
        <h3 class="text-sm font-bold text-slate-800">単語・表現の手動登録</h3>

        <form id="form-manual-add" class="space-y-3">
          <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label class="block text-xs font-bold text-slate-700 mb-1">日本語 <span class="text-rose-500">*</span></label>
              <input type="text" id="manual-ja" required placeholder="例: 食べる" class="w-full text-xs p-2.5 border border-slate-300 rounded-lg focus:border-emerald-500 focus:outline-hidden">
            </div>

            <div>
              <label class="block text-xs font-bold text-slate-700 mb-1">モンゴル語（キリル文字） <span class="text-rose-500">*</span></label>
              <input type="text" id="manual-mn" required placeholder="例: идэх" class="w-full text-xs p-2.5 border border-slate-300 rounded-lg focus:border-emerald-500 focus:outline-hidden cyrillic-text cyrillic-input" data-cyrillic="true">
              <!-- クイックバー -->
              <div class="flex items-center gap-1 overflow-x-auto py-1 scrollbar-none mt-1">
                ${SPECIAL_CYRILLIC_BAR.slice(0, 8).map(c => `
                  <button type="button" class="btn-quick-char-manual px-1.5 py-0.5 text-[10px] font-bold bg-slate-100 text-slate-700 rounded border border-slate-200" data-char="${c}">${c}</button>
                `).join('')}
              </div>
            </div>
          </div>

          <div class="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div>
              <label class="block text-xs font-bold text-slate-700 mb-1">語幹（動詞の場合）</label>
              <input type="text" id="manual-root" placeholder="例: ид-" class="w-full text-xs p-2.5 border border-slate-300 rounded-lg cyrillic-text cyrillic-input" data-cyrillic="true">
            </div>

            <div>
              <label class="block text-xs font-bold text-slate-700 mb-1">品詞</label>
              <select id="manual-pos" class="w-full text-xs p-2.5 border border-slate-300 rounded-lg bg-white">
                <option value="動詞">動詞</option>
                <option value="名詞">名詞</option>
                <option value="形容詞">形容詞</option>
                <option value="副詞">副詞</option>
                <option value="代名詞">代名詞</option>
                <option value="助詞">助詞</option>
                <option value="あいさつ">あいさつ・表現</option>
                <option value="名詞句">名詞句 / 動詞句</option>
              </select>
            </div>

            <div>
              <label class="block text-xs font-bold text-slate-700 mb-1">カテゴリー</label>
              <input type="text" id="manual-category" placeholder="例: 自作単語 / 日常会話" class="w-full text-xs p-2.5 border border-slate-300 rounded-lg">
            </div>
          </div>

          <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label class="block text-xs font-bold text-slate-700 mb-1">例文（モンゴル語）</label>
              <input type="text" id="manual-ex-mn" placeholder="例: Би хоол идсэн." class="w-full text-xs p-2.5 border border-slate-300 rounded-lg cyrillic-text cyrillic-input" data-cyrillic="true">
            </div>

            <div>
              <label class="block text-xs font-bold text-slate-700 mb-1">例文の日本語訳</label>
              <input type="text" id="manual-ex-ja" placeholder="例: 私はご飯を食べました。" class="w-full text-xs p-2.5 border border-slate-300 rounded-lg">
            </div>
          </div>

          <div>
            <label class="block text-xs font-bold text-slate-700 mb-1">メモ・注意点（格支配や例外）</label>
            <input type="text" id="manual-note" placeholder="例: 過去形は идсэн。女性母音語尾が接続。" class="w-full text-xs p-2.5 border border-slate-300 rounded-lg">
          </div>

          <button type="submit" class="w-full py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs shadow-md transition-all active:scale-95">
            ＋ 教材に登録する
          </button>
        </form>
      </div>
    `;
  }

  // --- 3. 登録教材一覧タブ ---
  static getListHTML() {
    const vocabList = StorageService.getVocabulary();
    const categories = Array.from(new Set(vocabList.map(v => v.category || 'その他'))).filter(Boolean);

    let displayList = vocabList;
    if (this.state.searchQuery) {
      const q = this.state.searchQuery.toLowerCase();
      displayList = displayList.filter(v => 
        (v.mongolian && v.mongolian.toLowerCase().includes(q)) || 
        (v.japanese && v.japanese.toLowerCase().includes(q)) ||
        (v.root && v.root.toLowerCase().includes(q))
      );
    }
    if (this.state.selectedCategory !== 'all') {
      displayList = displayList.filter(v => v.category === this.state.selectedCategory);
    }

    return `
      <div class="bg-white rounded-2xl p-5 border border-slate-200 shadow-xs space-y-4">
        <!-- 検索と絞り込み -->
        <div class="flex flex-col sm:flex-row gap-2">
          <input type="text" id="input-vocab-search" value="${this.state.searchQuery}" placeholder="単語を検索（日本語またはキリル文字）..." class="flex-1 text-xs p-2.5 border border-slate-300 rounded-lg">
          <select id="select-vocab-filter-cat" class="text-xs p-2.5 border border-slate-300 rounded-lg bg-white">
            <option value="all">すべてのカテゴリー (${vocabList.length})</option>
            ${categories.map(c => `<option value="${c}" ${this.state.selectedCategory === c ? 'selected' : ''}>${c}</option>`).join('')}
          </select>
        </div>

        <!-- 一覧テーブル（スマホでは見やすいカード形式） -->
        <div class="divide-y divide-slate-100 max-h-96 overflow-y-auto">
          ${displayList.length === 0 ? `
            <div class="text-center py-8 text-xs text-slate-400">見つかりませんでした。</div>
          ` : displayList.map(item => `
            <div class="py-3 flex flex-col sm:flex-row sm:items-center justify-between gap-2 hover:bg-slate-50 px-2 rounded-lg transition-colors">
              <div>
                <div class="flex items-center gap-2">
                  <span class="text-base font-bold text-slate-900 cyrillic-text">${item.mongolian}</span>
                  <span class="text-xs font-semibold text-emerald-800">${item.japanese}</span>
                  ${item.pos ? `<span class="text-[10px] px-1.5 py-0.5 rounded bg-slate-100 text-slate-600">${item.pos}</span>` : ''}
                </div>
                <div class="text-[11px] text-slate-500 flex flex-wrap gap-x-3 gap-y-0.5 mt-0.5">
                  ${item.root ? `<span>語幹: <span class="font-semibold cyrillic-text text-slate-700">${item.root}</span></span>` : ''}
                  ${item.pronunciation ? `<span>読み: ${item.pronunciation}</span>` : ''}
                  ${item.category ? `<span class="text-slate-400">${item.category}</span>` : ''}
                </div>
                ${item.note ? `<div class="text-[11px] text-slate-600 mt-0.5">💡 ${item.note}</div>` : ''}
              </div>

              <div class="flex items-center gap-1.5 self-end sm:self-center">
                <button type="button" class="btn-delete-item text-xs text-slate-400 hover:text-rose-600 px-2 py-1 rounded" data-id="${item.id}">
                  削除
                </button>
              </div>
            </div>
          `).join('')}
        </div>
      </div>
    `;
  }

  // --- 4. バックアップ・復元タブ ---
  static getBackupHTML() {
    return `
      <div class="bg-white rounded-2xl p-5 border border-slate-200 shadow-xs space-y-5">
        <div>
          <h3 class="text-sm font-bold text-slate-800 mb-1">データのバックアップ・復元・共有</h3>
          <p class="text-xs text-slate-500 leading-relaxed">
            教材データ、学習履歴、間違いノートをJSONファイルとして保存したり、スマートフォンとPC間で同じ教材を同期できます。また、単語リストをCSVとして出力してExcelで開くことも可能です。
          </p>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2">
          
          <!-- JSONバックアップ -->
          <div class="p-4 rounded-xl border border-slate-200 bg-slate-50 space-y-2">
            <h4 class="text-xs font-bold text-slate-800 flex items-center gap-1">
              <span>💾</span> 完全バックアップ (JSON)
            </h4>
            <p class="text-[11px] text-slate-500">
              全単語、文法、間違いノート、学習履歴を丸ごと保存します。
            </p>
            <button type="button" id="btn-export-json" class="w-full py-2 bg-slate-800 hover:bg-slate-900 text-white rounded-lg text-xs font-bold transition-all active:scale-95">
              JSONファイルをダウンロード
            </button>
          </div>

          <!-- CSVエクスポート -->
          <div class="p-4 rounded-xl border border-slate-200 bg-slate-50 space-y-2">
            <h4 class="text-xs font-bold text-slate-800 flex items-center gap-1">
              <span>📊</span> 単語リスト出力 (CSV)
            </h4>
            <p class="text-[11px] text-slate-500">
              登録単語一覧をExcel等で編集できるCSV形式で出力します。
            </p>
            <button type="button" id="btn-export-csv" class="w-full py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold transition-all active:scale-95">
              CSVファイルをダウンロード
            </button>
          </div>

        </div>

        <!-- JSON復元・インポート -->
        <div class="p-4 rounded-xl border border-sky-200 bg-sky-50/50 space-y-2.5">
          <h4 class="text-xs font-bold text-sky-900 flex items-center gap-1">
            <span>📥</span> バックアップファイルから復元
          </h4>
          <p class="text-[11px] text-sky-800">
            保存したJSONファイルを選択して、教材や履歴を復元・同期します。
          </p>
          <input type="file" id="input-import-file" accept=".json" class="text-xs w-full text-slate-600 file:mr-2 file:py-1.5 file:px-3 file:rounded-md file:border-0 file:text-xs file:font-semibold file:bg-sky-600 file:text-white hover:file:bg-sky-700 cursor-pointer">
        </div>

        <!-- 初期データリセット -->
        <div class="pt-3 border-t border-slate-100 flex items-center justify-between text-xs">
          <span class="text-slate-500 font-medium">全単語（862語）・全文法（48項目）に同期:</span>
          <button type="button" id="btn-reset-default" class="px-3 py-1.5 bg-rose-50 text-rose-600 hover:bg-rose-100 rounded-lg font-bold border border-rose-200 transition-all">
            最新マスターデータに同期
          </button>
        </div>
      </div>
    `;
  }

  // --- イベントバインド ---
  static bindEvents() {
    const homeBtn = this.container.querySelector('#btn-back-home');
    if (homeBtn) {
      homeBtn.addEventListener('click', () => {
        if (this.onNavigate) this.onNavigate('home');
      });
    }

    // サブタブ切り替え
    this.container.querySelectorAll('.subtab-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        this.state.subTab = btn.getAttribute('data-tab');
        this.renderView();
      });
    });

    if (this.state.subTab === 'paste') {
      const parseBtn = this.container.querySelector('#btn-parse-text');
      const sampleBtn = this.container.querySelector('#btn-load-sample-text');
      const textarea = this.container.querySelector('#textarea-paste-input');
      const commitBtn = this.container.querySelector('#btn-commit-batch');

      if (sampleBtn && textarea) {
        sampleBtn.addEventListener('click', () => {
          textarea.value = `日本語：食べる\nモンゴル語：идэх\n語幹：ид\n品詞：動詞\nメモ：女性母音語尾\n\n日本語：行く\nモンゴル語：явах\n語幹：яв\n品詞：動詞\n\n日本語：学校\nモンゴル語：сургууль\n品詞：名詞`;
        });
      }

      if (parseBtn && textarea) {
        parseBtn.addEventListener('click', () => {
          const raw = textarea.value;
          const parsed = TextParserService.parseText(raw);
          if (parsed.length === 0) {
            alert('解析できる単語データが見つかりませんでした。フォーマットを確認してください。');
            return;
          }
          this.state.parsedPreviewItems = parsed;
          this.renderView();
        });
      }

      if (commitBtn) {
        commitBtn.addEventListener('click', () => {
          if (this.state.parsedPreviewItems.length === 0) return;
          const count = StorageService.addVocabularyBatch(this.state.parsedPreviewItems);
          alert(`${count} 件の教材データを一括登録しました！`);
          this.state.parsedPreviewItems = [];
          this.state.subTab = 'list';
          this.renderView();
        });
      }

      // プレビューのインライン編集反映
      this.container.querySelectorAll('.preview-edit-field').forEach(input => {
        input.addEventListener('input', (e) => {
          const idx = parseInt(input.getAttribute('data-idx'), 10);
          const field = input.getAttribute('data-field');
          if (this.state.parsedPreviewItems[idx]) {
            this.state.parsedPreviewItems[idx][field] = e.target.value;
          }
        });
      });

      // 行削除
      this.container.querySelectorAll('.btn-remove-preview-row').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.getAttribute('data-idx'), 10);
          this.state.parsedPreviewItems.splice(idx, 1);
          this.renderView();
        });
      });
    }

    if (this.state.subTab === 'manual') {
      const form = this.container.querySelector('#form-manual-add');
      if (form) {
        form.addEventListener('submit', (e) => {
          e.preventDefault();
          const item = {
            japanese: this.container.querySelector('#manual-ja').value.trim(),
            mongolian: this.container.querySelector('#manual-mn').value.trim(),
            root: this.container.querySelector('#manual-root').value.trim(),
            pos: this.container.querySelector('#manual-pos').value,
            category: this.container.querySelector('#manual-category').value.trim() || '自作登録',
            exampleMn: this.container.querySelector('#manual-ex-mn').value.trim(),
            exampleJa: this.container.querySelector('#manual-ex-ja').value.trim(),
            note: this.container.querySelector('#manual-note').value.trim(),
            priority: '★★★'
          };
          StorageService.addVocabularyItem(item);
          alert('単語を登録しました！');
          form.reset();
        });
      }

      this.container.querySelectorAll('.btn-quick-char-manual').forEach(btn => {
        btn.addEventListener('click', () => {
          const char = btn.getAttribute('data-char');
          const mnInput = this.container.querySelector('#manual-mn');
          if (mnInput) {
            CyrillicKeyboard.setActiveInput(mnInput);
            CyrillicKeyboard.insertChar(char);
          }
        });
      });
    }

    if (this.state.subTab === 'list') {
      const searchInput = this.container.querySelector('#input-vocab-search');
      if (searchInput) {
        searchInput.addEventListener('input', (e) => {
          this.state.searchQuery = e.target.value;
          this.renderView();
        });
      }

      const catFilter = this.container.querySelector('#select-vocab-filter-cat');
      if (catFilter) {
        catFilter.addEventListener('change', (e) => {
          this.state.selectedCategory = e.target.value;
          this.renderView();
        });
      }

      this.container.querySelectorAll('.btn-delete-item').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-id');
          if (confirm('この単語を削除しますか？')) {
            StorageService.deleteVocabularyItem(id);
            this.renderView();
          }
        });
      });
    }

    if (this.state.subTab === 'backup') {
      // JSONエクスポート
      const exportJsonBtn = this.container.querySelector('#btn-export-json');
      if (exportJsonBtn) {
        exportJsonBtn.addEventListener('click', () => {
          const jsonStr = StorageService.exportAllDataJSON();
          const blob = new Blob([jsonStr], { type: 'application/json' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `mongol_learning_backup_${new Date().toISOString().split('T')[0]}.json`;
          a.click();
          URL.revokeObjectURL(url);
        });
      }

      // CSVエクスポート
      const exportCsvBtn = this.container.querySelector('#btn-export-csv');
      if (exportCsvBtn) {
        exportCsvBtn.addEventListener('click', () => {
          const csvStr = StorageService.exportVocabularyCSV();
          const bom = new Uint8Array([0xEF, 0xBB, 0xBF]); // Excel UTF-8 BOM
          const blob = new Blob([bom, csvStr], { type: 'text/csv;charset=utf-8;' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `mongol_vocabulary_${new Date().toISOString().split('T')[0]}.csv`;
          a.click();
          URL.revokeObjectURL(url);
        });
      }

      // JSON復元
      const fileInput = this.container.querySelector('#input-import-file');
      if (fileInput) {
        fileInput.addEventListener('change', (e) => {
          const file = e.target.files[0];
          if (!file) return;
          const reader = new FileReader();
          reader.onload = (evt) => {
            const content = evt.target.result;
            const res = StorageService.importAllDataJSON(content);
            if (res.success) {
              alert(`復元が完了しました！（${res.count}件の単語データを復元）`);
              this.renderView();
            } else {
              alert(`復元エラー: ${res.error}`);
            }
          };
          reader.readAsText(file);
        });
      }

      // 初期リセット
      const resetBtn = this.container.querySelector('#btn-reset-default');
      if (resetBtn) {
        resetBtn.addEventListener('click', () => {
          if (confirm('登録データを標準の初期状態に復元しますか？（自作単語は初期化されます）')) {
            StorageService.resetVocabularyToDefault();
            alert('初期データに復元しました。');
            this.renderView();
          }
        });
      }
    }
  }
}


